.02],[57.43,60.33],[61.15,70.58],[64.71,74.21],[69.04,75.87],[72.91,76.03],[77.09,74.88],[80.5,72.56],[82.66,69.75],[83.75,66.94],[83.9,63.47],[83.13,60.33],[81.42,57.36],[79.1,55.04],[69.97,50.41],[67.65,47.27],[66.87,43.31],[67.18,35.87],[68.89,29.75],[70.59,26.78],[76.47,21.16]]]}},"punto":[15.48,42.15],"pista":"Es la zona pálida que rodea a la mariposa.","exp":"Axones mielinizados que suben y bajan por la médula (los cordones)."},{"clave":"canal-central","nombre":"Canal central","zona":{"e":[[51.39,51.07,2.48,2.64]]},"punto":[51.39,51.07],"pista":"Es el pequeño orificio en el centro de la mariposa.","exp":"Resto del tubo neural, revestido por células ependimarias; tiene líquido cefalorraquídeo."},{"clave":"fisura-ventral","nombre":"Fisura media ventral","zona":{"r":[[47.37,71.9,8.36,23.97]]},"punto":[51.39,86.78],"pista":"Es la hendidura ancha del borde, en la línea media, abajo.","exp":"Marca el lado ventral: es más ancha y profunda que el tabique dorsal."},{"clave":"tabique-dorsal","nombre":"Tabique medio dorsal","zona":{"r":[[48.61,4.13,5.57,40.5]]},"punto":[51.39,14.05],"pista":"Es la línea delgada que baja desde el borde de arriba hasta la mariposa.","exp":"Divide en dos los cordones dorsales; marca el lado dorsal."}],"orden":[],"preguntas":[{"p":"¿Cómo reconoces el lado ventral de este corte?","ops":["Por la fisura media ventral y las astas anchas con somas grandes","Por el tabique medio dorsal y las astas delgadas sin somas grandes","Por el canal central, que siempre queda junto al borde ventral","Por la sustancia blanca, que sólo rodea a la médula por ese lado"],"ok":0,"pista":"Busca la hendidura del borde y el asta donde están las neuronas más grandes.","exp":"El lado ventral tiene la fisura media ventral (una hendidura profunda) y las astas ventrales, anchas, con las motoneuronas. El dorsal tiene un tabique delgado y astas dorsales angostas."},{"p":"Según tu orientación, ¿qué llega al asta dorsal y qué sale del asta ventral?","ops":["Llega información sensitiva por la raíz dorsal y salen órdenes motoras por la ventral","Llegan órdenes motoras por la raíz dorsal y sale información sensitiva por la ventral","Llega líquido cefalorraquídeo del canal y sale mielina hacia la sustancia blanca","Llegan axones del encéfalo por la raíz dorsal y salen hacia el encéfalo por la ventral"],"ok":0,"pista":"Dorsal = entrada sensitiva; ventral = salida motora.","exp":"Es la ley de Bell-Magendie: la raíz dorsal es sensitiva (entrada) y la ventral es motora (salida). Por eso el asta dorsal recibe y el asta ventral, con sus motoneuronas, envía."}]}]},{"n":2,"tipo":"rompecabezas","titulo":"Los extremos del arco","tablero":"img/reflejo/tablero-huecos.jpg","huecos":true,"instrucciones":"La médula ya está. Completa los huecos punteados: toca un hueco y elige su pieza, o arrastra la pieza a cualquier parte de su hueco. Primero el lado <strong>sensitivo</strong> (lo que trae la información) y después el <strong>motor</strong> (lo que la lleva al músculo). <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","grupos":{"sensitivo":"1. Lado sensitivo: receptores → nervio → ganglio → raíz dorsal","motor":"2. Lado motor: raíz ventral → nervio → músculo"},"piezas":[{"clave":"piel","nombre":"Piel","grupo":"sensitivo","img":"img/reflejo/piezas/piel.webp","caja":[1.76,8.5,25.65,21.97],"zona":{"p":[[[1.82,14.16],[1.89,28.22],[2.47,29.49],[19.53,30.27],[21.35,29.3],[24.54,29.3],[27.28,24.61],[27.28,10.74],[26.5,9.77],[22.33,9.77],[19.99,9.08],[16.02,9.77],[13.35,8.98],[10.29,9.38],[7.36,8.59],[5.99,9.38]]]},"pista":"El bloque de arriba, con sus capas.","exp":"Tiene receptores: las terminaciones libres de dolor y temperatura inician el reflejo de retirada."},{"clave":"musculo-extensor","nombre":"Músculo con huso (extensor)","grupo":"sensitivo","img":"img/reflejo/piezas/musculo-extensor.webp","caja":[1.17,39.55,36.59,21.48],"zona":{"p":[[[1.24,48.73],[1.37,50.29],[3.65,51.17],[8.14,56.25],[10.61,58.4],[13.54,59.96],[17.51,60.84],[21.35,60.74],[25.0,59.77],[27.34,58.5],[33.14,53.81],[36.33,53.03],[36.46,53.91],[37.63,53.12],[37.57,47.27],[35.87,47.95],[33.66,47.56],[28.26,43.16],[28.71,42.77],[27.41,41.89],[25.85,41.89],[22.59,40.43],[19.73,39.75],[16.28,39.65],[13.54,40.14],[9.9,41.6],[5.21,44.73],[3.45,45.12],[1.82,44.53],[1.63,45.61],[2.15,46.09],[1.5,46.58],[1.82,47.07],[1.3,47.85],[1.5,48.24]]]},"pista":"El músculo del medio: en su interior se ve el huso.","exp":"Su huso muscular detecta el estiramiento: es el receptor del reflejo rotuliano. Además es efector (se contrae)."},{"clave":"nervio","nombre":"Nervio espinal y sus ramos","grupo":"sensitivo","img":"img/reflejo/piezas/nervio.webp","caja":[16.93,23.73,41.73,40.23],"zona":{"p":[[[16.99,30.47],[21.22,30.96],[24.48,32.71],[26.11,34.96],[27.8,38.38],[29.62,40.53],[27.47,41.7],[28.84,42.68],[31.9,42.38],[39.39,45.21],[37.7,47.17],[37.7,53.03],[36.33,54.1],[35.42,57.71],[34.38,59.86],[31.38,62.89],[32.75,63.77],[34.51,62.3],[36.07,59.96],[37.3,56.74],[38.74,51.17],[40.76,47.95],[42.32,46.68],[43.82,46.09],[46.22,46.19],[47.92,46.78],[47.98,44.24],[47.53,43.85],[48.37,41.6],[50.65,38.57],[51.5,37.99],[55.34,38.38],[57.88,37.11],[55.47,37.79],[53.39,37.21],[51.82,35.84],[50.39,33.01],[48.57,35.94],[44.27,40.33],[41.02,41.5],[36.98,41.5],[33.46,40.43],[30.08,38.28],[28.12,35.64],[25.98,31.84],[24.09,30.08],[24.35,29.39],[21.35,29.39],[19.53,30.37]]]},"pista":"La vía que se ramifica hacia la piel y los músculos.","exp":"Une la raíz dorsal y la ventral: es mixto (sensitivo y motor). Sus ramos llegan a la piel y a los músculos."},{"clave":"ganglio","nombre":"Ganglio de la raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/ganglio.webp","caja":[50.39,23.73,10.55,14.16],"zona":{"p":[[[59.11,25.2],[57.23,23.83],[55.4,24.61],[53.45,26.37],[51.82,28.91],[50.46,32.71],[51.24,34.86],[53.06,36.91],[55.47,37.7],[57.55,37.11],[59.11,35.74],[60.48,32.91],[60.81,30.47],[60.48,28.03]]]},"pista":"El abultamiento entre el nervio y la médula, del lado de arriba.","exp":"Tiene los somas de las neuronas sensitivas (pseudounipolares) rodeados de células satélite."},{"clave":"raiz-dorsal","nombre":"Raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/raiz-dorsal.webp","caja":[58.53,21.29,10.22,10.06],"zona":{"p":[[[68.62,21.68],[66.15,21.48],[61.39,24.61],[60.42,24.61],[58.92,23.83],[58.59,23.93],[58.59,24.51],[60.16,26.86],[61.0,31.15],[62.37,28.42],[64.45,26.66]]]},"pista":"Une el ganglio con el lado dorsal de la médula.","exp":"Lleva la rama central de las sensitivas hasta el asta dorsal."},{"clave":"raiz-ventral","nombre":"Raíz ventral","grupo":"motor","img":"img/reflejo/piezas/raiz-ventral.webp","caja":[47.98,44.14,14.78,17.38],"zona":{"p":[[[48.05,44.34],[48.05,46.88],[49.22,47.85],[53.71,55.18],[56.12,57.32],[60.55,59.57],[62.04,61.33],[62.63,61.23],[60.87,56.74],[59.9,52.73],[59.83,54.59],[57.94,54.69],[56.38,54.0],[54.36,52.15],[50.65,46.09]]]},"pista":"Sale del lado ventral de la médula, el de las astas anchas.","exp":"Lleva los axones de las motoneuronas desde el asta ventral hacia el nervio."},{"clave":"musculo-flexor","nombre":"Músculo flexor","grupo":"motor","img":"img/reflejo/piezas/musculo-flexor.webp","caja":[1.95,62.79,43.88,27.73],"zona":{"p":[[[2.15,69.43],[2.15,70.7],[5.6,73.54],[9.96,80.27],[13.15,84.38],[17.06,87.79],[20.7,89.65],[24.02,90.33],[28.32,90.14],[38.8,86.43],[41.21,86.62],[44.47,87.79],[44.66,86.13],[45.05,85.55],[45.12,83.98],[45.44,83.59],[45.31,83.01],[45.7,82.62],[41.34,80.27],[35.09,70.51],[32.42,67.87],[30.21,66.41],[30.21,65.72],[32.68,63.87],[31.38,62.99],[27.99,65.43],[24.02,63.57],[20.12,62.89],[14.65,63.48],[7.75,66.6],[5.92,66.5],[3.52,65.33],[3.58,65.92],[3.12,66.31],[3.39,66.7],[2.86,67.19],[3.19,67.68],[2.41,68.36],[2.6,68.75]]]},"pista":"El músculo de abajo, al final del ramo que baja.","exp":"Efector del reflejo de retirada: al contraerse, aleja la extremidad del estímulo."}],"preguntas":[{"p":"¿Por qué la raíz dorsal tiene un ganglio y la ventral no?","ops":["Los somas sensitivos están fuera de la médula; los motores, dentro","La raíz dorsal es más larga y necesita un relevo en el camino","En el ganglio ocurre la sinapsis entre la sensitiva y la motora","La raíz ventral no lleva axones, sólo glía y vasos sanguíneos"],"ok":0,"pista":"¿Dónde están los somas de las motoneuronas? ¿Y los de las sensitivas?","exp":"El ganglio agrupa los somas de las neuronas sensitivas, fuera del SNC. Los somas motores están dentro, en el asta ventral, así que la raíz ventral sólo lleva axones. En el ganglio no hay sinapsis."},{"p":"El nervio espinal lleva juntos axones sensitivos y motores. ¿Cómo se clasifica?","ops":["Mixto: lleva fibras sensitivas y motoras a la vez","Sensitivo: sólo lleva información hacia la médula","Motor: sólo lleva las órdenes hacia los músculos","Autónomo: sólo controla las vísceras y glándulas"],"ok":0,"pista":"Recuerda qué raíces se unen para formarlo.","exp":"Todos los nervios espinales son mixtos: reciben fibras de la raíz dorsal (sensitivas) y de la ventral (motoras). Por eso una lesión del nervio afecta la sensibilidad y la fuerza a la vez."}]},{"n":3,"tipo":"circuito","titulo":"Reflejo rotuliano","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Al golpear el tendón se estira el extensor. <strong>1. Ubica</strong> cada neurona tocando dónde está su soma (aparece al acertar). <strong>2. Conecta</strong> las dos vías tocando las neuronas en el orden en que viaja la información. <strong>3. Lupas</strong>: toca cada 🔍 y responde. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"rotuliano","titulo":"Reflejo rotuliano","sub":"con inhibición recíproca","estimulo":"Golpe del martillo en el tendón bajo la rótula: el cuádriceps (extensor) se estira.","receptor":"Huso muscular","efector":"Extensor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del huso","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#2563EB","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio.","trazo":{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]],"lbl":[0,-36,"middle"]}},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al extensor, el mismo músculo que se estiró.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[76.17,45.9],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del músculo antagonista.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1170,470,18],"d":["M1165,488 C1162,515 1155,540 1140,562"],"fino":[],"botones":[[1138,565,6],[1148,566,6]],"lbl":[28,-6,"start"]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al flexor, el antagonista.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]],"lbl":[0,50,"middle"]}}],"vias":[{"titulo":"Vía directa","orden":["sensitiva","motora-ext"],"pista":"Empieza por la neurona que recibe del huso; ¿con quién hace sinapsis directo?","exp":"Huso → sensitiva (ganglio, raíz dorsal) → motoneurona del extensor (asta ventral, raíz ventral) → el extensor se contrae: una sola sinapsis central.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512 L1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-flex"],"inhibe":"motora-flex","pista":"La colateral de la sensitiva pasa por una interneurona antes de llegar al flexor.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del flexor, que queda frenada: el antagonista se relaja.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 L1133,395 C1145,420 1155,440 1160,458 L1170,470 L1165,488 C1162,515 1155,540 1140,562 L1118,585"}],"lupas":[{"clave":"huso","titulo":"Huso muscular","img":"img/reflejo/huso-muscular.jpg","x":262,"y":520,"preguntas":[{"p":"¿Qué estímulo activa a la terminación azul enrollada en el huso?","ops":["El estiramiento del músculo, que deforma las fibras intrafusales","La contracción voluntaria del músculo, que acorta las fibras","El dolor del golpe del martillo sobre la piel de la rodilla","La acetilcolina liberada por la motoneurona sobre el huso"],"ok":0,"pista":"Piensa en qué le hace el martillo al tendón y al músculo.","exp":"El golpe estira el tendón y el cuádriceps; el estiramiento deforma la terminación anuloespiral y abre canales iónicos: nace el potencial en la neurona sensitiva."},{"p":"¿En qué se diferencian las fibras del huso de las del resto del músculo?","ops":["Son intrafusales: detectan longitud y casi no aportan fuerza","Son extrafusales: generan casi toda la fuerza del músculo","Son nerviosas: forman parte del axón de la neurona sensitiva","Son tendinosas: unen el músculo con el hueso de la rótula"],"ok":0,"pista":"El huso está dentro de una cápsula.","exp":"Las fibras intrafusales están dentro de la cápsula del huso y funcionan como sensor de longitud; las extrafusales hacen la fuerza."}]},{"clave":"excitatoria","titulo":"Sinapsis excitatoria (azul → roja)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1098,"y":492,"preguntas":[{"p":"¿Qué neurotransmisor libera la sensitiva sobre la motoneurona?","ops":["Glutamato, que excita a la motoneurona","GABA, que inhibe a la motoneurona","Acetilcolina, que contrae al músculo","Glicina, que frena a la motoneurona"],"ok":0,"pista":"Es el principal neurotransmisor excitatorio del sistema nervioso central.","exp":"La sensitiva libera glutamato: abre canales de Na⁺ en la motoneurona, que se despolariza y dispara."},{"p":"En la lupa, ¿qué lado es presináptico y cuál postsináptico?","ops":["Presináptico: el botón azul con vesículas; postsináptico: la roja","Presináptico: la roja con receptores; postsináptico: el botón azul","Ambos son presinápticos, porque los dos liberan vesículas","Ninguno: la hendidura es una unión directa entre citoplasmas"],"ok":0,"pista":"Las vesículas están en la neurona que envía.","exp":"El botón de la sensitiva (azul) tiene las vesículas y libera; la motoneurona (roja) tiene los receptores. Entre ambos queda la hendidura sináptica."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → naranja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1178,"y":575,"preguntas":[{"p":"¿Qué hace la interneurona morada sobre la motoneurona naranja?","ops":["La inhibe con glicina o GABA y el flexor se relaja","La excita con glutamato y el flexor se contrae","La inhibe con acetilcolina y el extensor se relaja","La excita con glicina y el extensor se contrae"],"ok":0,"pista":"Mira el color de la lupa: es la sinapsis inhibitoria.","exp":"La interneurona inhibitoria libera glicina (o GABA), abre canales de Cl⁻ e hiperpolariza a la motoneurona del flexor: el músculo antagonista se relaja."},{"p":"¿Para qué sirve frenar al flexor mientras se contrae el extensor?","ops":["Para que el antagonista no se oponga y la pierna se extienda","Para que el flexor descanse y se recupere del golpe del martillo","Para que la señal suba al encéfalo antes de contraer el extensor","Para que el huso del flexor deje de estirarse y se apague"],"ok":0,"pista":"Si los dos músculos se contrajeran a la vez, ¿se movería la rodilla?","exp":"Es la inhibición recíproca: mientras el agonista se contrae, el antagonista se relaja y el movimiento es eficiente."}]},{"clave":"placa","titulo":"Placa motora","img":"img/reflejo/placa-motora.jpg","x":470,"y":500,"preguntas":[{"p":"¿Qué neurotransmisor libera la motoneurona en la placa motora?","ops":["Acetilcolina, que abre canales en la fibra muscular","Glutamato, que abre canales en la fibra muscular","Glicina, que relaja la fibra muscular al instante","Noradrenalina, que acelera la fibra muscular"],"ok":0,"pista":"Es el mismo neurotransmisor de todas las uniones neuromusculares del músculo esquelético.","exp":"La acetilcolina se une a receptores nicotínicos de la fibra muscular, la despolariza y desencadena la contracción."},{"p":"¿Para qué sirven los pliegues de la membrana muscular bajo el botón?","ops":["Aumentan la superficie con receptores de acetilcolina","Guardan las vesículas de acetilcolina de la motoneurona","Aíslan la fibra para que el impulso no se escape","Producen la mielina que envuelve al axón motor"],"ok":0,"pista":"Fíjate qué hay en la membrana de los pliegues.","exp":"Los pliegues de la unión neuromuscular multiplican la superficie con receptores: cada impulso libera acetilcolina suficiente para contraer la fibra."}]}],"preguntas":[{"p":"¿Cómo se clasifica el reflejo rotuliano?","ops":["Monosináptico: una sola sinapsis central, sin interneurona","Polisináptico: varias sinapsis centrales, con interneuronas","Monosináptico: una sola neurona, que es sensitiva y motora","Polisináptico: varias sinapsis dentro del ganglio dorsal"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es monosináptico: es el reflejo más rápido. Por eso se usa para evaluar el arco reflejo (nervio, raíz, segmento medular y músculo)."},{"p":"Si la vía directa es monosináptica, ¿por qué hay una interneurona en este reflejo?","ops":["Frena al antagonista: es otra vía, en paralelo a la directa","Retrasa la contracción del extensor para que sea más suave","Lleva la información del huso hacia el encéfalo para sentirla","Reemplaza a la motoneurona cuando el golpe es muy fuerte"],"ok":0,"pista":"Mira hacia qué motoneurona va la morada.","exp":"La vía directa (sensitiva → motoneurona del extensor) tiene una sola sinapsis. La interneurona está en una vía paralela que inhibe al flexor."}]}]},{"n":4,"tipo":"circuito","titulo":"Reflejo de retirada","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Pisas un clavo. Las dos motoneuronas ya están. <strong>1. Ubica</strong> la sensitiva y las dos interneuronas. <strong>2. Conecta</strong> las dos vías. <strong>3. Lupas</strong>. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"retirada","titulo":"Reflejo de retirada","sub":"polisináptico","estimulo":"Pisas un clavo: el pie se retira antes de que sientas el dolor.","receptor":"Nociceptor (piel)","efector":"Flexor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del dolor","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#0891B2","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio. Sus terminaciones libres en la piel son nociceptores.","trazo":{"color":"#0891B2","ico":"Pseudounipolar","soma":[850,298,24],"d":["M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1116,346"],"fino":["M228,285 L83,213 M228,285 L114,208 M228,285 L157,206 M228,285 L190,204 M228,285 L235,203 M228,285 L277,209","M1105,310 C1135,345 1160,400 1176,430"],"botones":[[83,213,5],[114,208,5],[157,206,5],[190,204,5],[235,203,5],[277,209,5],[1118,350,7],[1109,345,6],[1176,433,6]],"lbl":[0,-36,"middle"]}},{"clave":"exc","nombre":"Interneurona excitatoria","detalle":"multipolar","icono":"Multipolar","color":"#16A34A","zona":{"p":[[[69.27,28.12],[69.08,28.42],[71.81,32.03],[72.4,33.69],[73.05,37.21],[73.18,41.41],[76.56,41.41],[76.56,40.43],[73.7,31.05],[72.59,29.59],[69.86,27.64],[69.6,28.32]]]},"zona_nombre":"Asta dorsal","punto":[73.89,36.62],"pista":"Está en el asta dorsal, donde termina la sensitiva del dolor.","exp":"Recibe a la sensitiva en el asta dorsal y excita a la motoneurona del flexor.","trazo":{"color":"#16A34A","ico":"Multipolar","soma":[1135,375,18],"d":["M1135,393 C1142,450 1135,520 1122,562"],"fino":[],"botones":[[1120,565,6],[1130,566,6]],"lbl":[28,-4,"start"]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[77.15,43.46],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del extensor.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1185,445,18],"d":["M1173,458 C1150,490 1100,520 1070,533"],"fino":[],"botones":[[1068,536,6],[1072,528,6]],"lbl":[28,-4,"start"]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]],"lbl":[0,50,"middle"]},"dada":true},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]},"dada":true}],"vias":[{"titulo":"Vía de la retirada","orden":["sensitiva","exc","motora-flex"],"pista":"Del nociceptor a la interneurona del asta dorsal, y de ahí al músculo que aleja el pie.","exp":"Nociceptor → sensitiva → interneurona excitatoria (asta dorsal) → motoneurona del flexor → el flexor retira el pie.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1118,350 L1135,375 L1135,393 C1142,450 1135,520 1122,562 L1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690 C400,715 360,735 325,755"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-ext"],"inhibe":"motora-ext","pista":"Ahora hay que relajar al músculo que se opone a la flexión.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del extensor, que queda frenada.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 C1135,345 1160,400 1176,430 L1185,445 L1173,458 C1150,490 1100,520 1070,533 L1045,545"}],"lupas":[{"clave":"excitatoria","titulo":"Sinapsis excitatoria (celeste → verde)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1172,"y":318,"preguntas":[{"p":"¿Qué cambia en la interneurona verde cuando la celeste libera glutamato?","ops":["Se despolariza y puede disparar hacia la motoneurona","Se hiperpolariza y deja de disparar hacia la motoneurona","Libera acetilcolina directamente sobre el músculo flexor","Envía el impulso de vuelta hacia la neurona sensitiva"],"ok":0,"pista":"El glutamato es excitatorio.","exp":"El glutamato abre canales catiónicos (entra Na⁺): la interneurona se despolariza y excita a la motoneurona del flexor."},{"p":"¿Por qué el reflejo de retirada tarda un poco más que el rotuliano?","ops":["Tiene más sinapsis: cada una suma un retardo sináptico","Su receptor está más lejos de la médula que el huso","Su motoneurona no tiene mielina y conduce muy lento","La señal pasa primero por el encéfalo antes de volver"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es polisináptico: cada sinapsis agrega cerca de 0,5–1 ms. Aun así no pasa por el encéfalo."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → roja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1112,"y":478,"preguntas":[{"p":"En la retirada, ¿qué motoneurona queda inhibida y por qué?","ops":["La del extensor, para que no se oponga al flexor","La del flexor, para que la pierna no se mueva","La del extensor, para que el huso deje de estirarse","La del flexor, para proteger el músculo del dolor"],"ok":0,"pista":"Ahora el que se contrae es el flexor.","exp":"Se invierte el rotuliano: el flexor se contrae y la interneurona inhibitoria frena al extensor (inhibición recíproca)."},{"p":"¿Qué distingue a una vesícula inhibitoria en la lupa?","ops":["Suele ser aplanada y contiene glicina o GABA","Es redonda y grande y contiene glutamato","Es densa y contiene acetilcolina para el músculo","No tiene contenido: sólo abre la hendidura"],"ok":0,"pista":"Compara la forma de las vesículas de las dos lupas sinápticas.","exp":"En la microscopía electrónica, las sinapsis inhibitorias suelen tener vesículas aplanadas (glicina o GABA) y las excitatorias, redondas (glutamato)."}]}],"preguntas":[{"p":"Al pisar el clavo contraes los flexores y a la vez se relajan los extensores. ¿Qué permite eso?","ops":["La interneurona, que reparte la señal: excita a unos y frena a otros","La sensitiva, que hace sinapsis directo con todos los músculos","La motoneurona, que envía órdenes opuestas por un solo axón","La raíz ventral, que separa las órdenes de contraer y relajar"],"ok":0,"pista":"¿Qué neurona tiene este circuito que el rotuliano no tiene?","exp":"Las interneuronas distribuyen la señal: excitan a las motoneuronas de los flexores e inhiben a las de los extensores (inervación recíproca). También pueden cruzar al otro lado para sostener el cuerpo."},{"p":"Retiras el pie antes de sentir el dolor. ¿Qué lo explica?","ops":["El circuito se cierra en la médula; la vía hacia el encéfalo es más larga","El dolor no llega al encéfalo hasta que el reflejo ya terminó","La interneurona bloquea el dolor mientras dura el movimiento","El encéfalo inicia el reflejo y después registra el dolor"],"ok":0,"pista":"¿Dónde se cierra el circuito que armaste? ¿Pasa por el encéfalo?","exp":"El reflejo se resuelve en el segmento medular. Al mismo tiempo, otras neuronas llevan la señal hacia el encéfalo, que la percibe como dolor un instante después."}]}]},{"n":5,"tipo":"circuito","titulo":"¿Dónde se cortó el arco?","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Los tres pacientes tienen el <strong>reflejo rotuliano disminuido o ausente</strong>. Lee cada caso, tócalo y luego toca el sitio (A, B o C) donde está la lesión. Fíjate en lo que acompaña al reflejo: ¿falla la sensibilidad, la fuerza o ambas? <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[],"neuronas":[{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]],"lbl":[0,-36,"middle"]},{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]}],"cortes":{"titulo":"¿Dónde se cortó el arco?","sitios":[{"letra":"A","x":560,"y":445,"nombre":"Nervio (mixto)"},{"letra":"B","x":930,"y":262,"nombre":"Raíz dorsal y ganglio"},{"letra":"C","x":1098,"y":578,"nombre":"Asta ventral (motoneurona)"}],"casos":[{"titulo":"Hernia lumbar","caso":"Hombre de 45 años con una hernia del disco L3-L4 que comprime la raíz L4. Tiene dolor y hormigueo en la cara anterior de la pierna y el rotuliano disminuido; la fuerza para extender la rodilla está casi normal.","sitio":"B","respuesta":"Raíz dorsal (y su ganglio)","pista":"Predominan el dolor y el hormigueo: ¿qué parte del arco trae la información?","exp":"La hernia comprime la raíz posterior: falla la entrada sensitiva (dolor radicular en el dermatoma) y el reflejo disminuye, aunque la motoneurona esté sana. Si la compresión es intensa también puede haber algo de debilidad."},{"titulo":"Atrofia muscular espinal","caso":"Niña de 3 años con atrofia muscular espinal: debilidad y atrofia de los muslos, fasciculaciones y rotuliano ausente. Siente bien el tacto y el dolor.","sitio":"C","respuesta":"Asta ventral (motoneurona)","pista":"La sensibilidad está intacta y el músculo se atrofia. ¿Dónde están los somas de la vía final común?","exp":"La atrofia muscular espinal (como la poliomielitis) destruye las motoneuronas del asta ventral: se pierden el reflejo y la fuerza, el músculo se atrofia y fascicula, pero la sensibilidad queda intacta."},{"titulo":"Lesión del nervio femoral","caso":"Mujer de 60 años que, tras una cirugía de cadera, no puede extender la rodilla, no tiene rotuliano y no siente la cara anterior del muslo.","sitio":"A","respuesta":"Nervio (mixto)","pista":"Fallan a la vez la sensibilidad y la fuerza del mismo territorio.","exp":"El nervio femoral lleva juntas las fibras sensitivas y las motoras del cuádriceps: su lesión quita sensibilidad, fuerza y reflejo en su territorio."}]}}]}', NULL, 1);

-- Actividad 10: CONOCE LA GLÍA (práctico 2) · ESTRUCTURA Y UBICACIÓN sobre esquemas. Niveles I-II «circuito» con etiquetas
-- (nombre por clic, zonas sombreadas y preguntas de forma o lugar; II usa img/glia-snp-tejido.jpg, ganglio → nervio);
-- nivel III práctica «elegir» con tarjetas de las 6 glías: descripción de forma o lugar → tarjeta → cuadro (sin funciones: van en «La glía en acción»)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (10, 7, 'glia-conoce', 'Conoce la glía',
       'Las seis células gliales: cómo son y dónde están. Nivel I: la glía del SNC en su tejido. Nivel II: la glía del SNP, del ganglio al nervio. Nivel III: reconoce cada célula por su forma y su lugar y arma el cuadro.',
       'lamina', 1, 'Reconocer las células gliales del SNC y del SNP por su forma y su ubicación en el tejido.', 'Etiquetar dos esquemas tocando cada estructura; leer descripciones de forma y lugar y tocar la tarjeta de la célula para completar un cuadro.', 'Clase Células del sistema nervioso II 2026 · esquemas de Kaira Santos y Fernanda López');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (10, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "circuito", "titulo": "Glía del SNC en su tejido", "fondo": "img/glia-snc-tejido.jpg", "etiquetas": true, "subtitulo": "La glía del SNC en su tejido", "instrucciones": "Primero ubica la <strong>sustancia gris</strong> y la <strong>sustancia blanca</strong> (las dos zonas sombreadas). Después elige cada nombre en el panel y toca la célula en el esquema; al final, mira el esquema y responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "zonas", "titulo": "Sustancia gris y blanca", "ayuda": "Elige un nombre y toca su zona sombreada en la imagen.", "mascara": [{"r": [0, 0, 47, 76], "c": "rgba(124,58,237,.38)"}, {"r": [53, 0, 47, 76], "c": "rgba(13,148,136,.38)"}], "piezas": [{"clave": "gris", "nombre": "Sustancia gris", "zona": {"r": [[0, 0, 49, 76]]}, "punto": [22, 40], "pista": "Es el lado donde están los somas de las neuronas y sus sinapsis.", "exp": "Somas, dendritas y sinapsis: aquí se procesa la información."}, {"clave": "blanca", "nombre": "Sustancia blanca", "zona": {"r": [[51, 0, 49, 76]]}, "punto": [78, 40], "pista": "Es el lado de los axones paralelos envueltos en mielina.", "exp": "Axones mielinizados que conducen la información entre regiones; la mielina le da su color blanco."}], "preguntas": []}, {"clave": "celulas", "titulo": "Las células", "ayuda": "Elige un nombre y toca la célula en la imagen (vale cualquier punto de la célula).", "piezas": [{"clave": "neurona", "nombre": "Neurona", "zona": {"e": [[16, 25, 7, 9], [24, 55, 6.5, 8]]}, "punto": [16, 25], "pista": "Es la célula violeta grande, con soma, dendritas y un axón que se mieliniza.", "exp": "No es glía: es la célula que la glía sostiene y protege."}, {"clave": "astro-proto", "nombre": "Astrocito protoplasmático", "zona": {"e": [[36.5, 31, 5, 7]]}, "punto": [36.5, 31], "pista": "Es la célula rosada en estrella de la sustancia gris, junto al capilar.", "exp": "Astrocito de la sustancia gris: muchas ramas cortas que rodean a las neuronas."}, {"clave": "astro-fibroso", "nombre": "Astrocito fibroso", "zona": {"e": [[92, 31, 6, 9]]}, "punto": [92, 31], "pista": "Es la célula rosada en estrella de la sustancia blanca, de ramas largas y rectas.", "exp": "Astrocito de la sustancia blanca: ramas largas entre los axones."}, {"clave": "oligo", "nombre": "Oligodendrocito", "zona": {"e": [[73.5, 40.5, 4.5, 6.5]]}, "punto": [73.5, 40.5], "pista": "Es la célula azul de la sustancia blanca: sus prolongaciones llegan a la mielina de varios axones.", "exp": "Forma la mielina de varios axones del SNC."}, {"clave": "microglia", "nombre": "Microglía", "zona": {"e": [[41, 54, 5, 7], [56.5, 12, 5, 7]]}, "punto": [41, 54], "pista": "Es la célula más pequeña, gris azulada y muy ramificada (hay dos).", "exp": "La célula de defensa del SNC."}, {"clave": "ependimaria", "nombre": "Célula ependimaria", "zona": {"r": [[0, 76, 100, 10]]}, "punto": [45, 81.5], "pista": "Son las células amarillas en fila que revisten la cavidad de abajo.", "exp": "Revisten los ventrículos y el canal central."}, {"clave": "capilar", "nombre": "Capilar", "zona": {"e": [[45.5, 14, 4.5, 11]]}, "punto": [45.5, 14], "pista": "Es el vaso con glóbulos rojos, arriba.", "exp": "Vaso sanguíneo: los astrocitos lo rodean con sus pies."}], "preguntas": [{"p": "En el esquema hay dos astrocitos, uno en cada sustancia. ¿Qué diferencia su forma?", "ops": ["El de la gris tiene ramas cortas y muy ramificadas; el de la blanca, ramas largas y rectas", "El de la gris no tiene núcleo; el de la blanca tiene un núcleo grande y central", "El de la gris envuelve axones con mielina; el de la blanca rodea los somas", "Son iguales: sólo cambia el color con que se dibujó cada uno"], "ok": 0, "pista": "Compara el largo y la cantidad de ramas de las dos células rosadas.", "exp": "Protoplasmático (sustancia gris): ramas cortas y muy ramificadas entre somas y sinapsis. Fibroso (sustancia blanca): ramas largas y rectas entre los axones."}, {"p": "Sigue las prolongaciones del oligodendrocito. ¿A cuántos axones llegan?", "ops": ["A varios axones: cada prolongación forma un tramo de mielina en un axón distinto", "A un solo axón: la célula se enrolla entera alrededor de él", "A ninguno: sus prolongaciones terminan en el capilar", "A los somas de las neuronas de la sustancia gris"], "ok": 0, "pista": "Cuenta los axones celestes que toca la célula azul.", "exp": "Un oligodendrocito mieliniza tramos (internodos) de varios axones a la vez: hasta unos 50."}, {"p": "Además de rodear a las neuronas, ¿con qué estructura se relacionan los pies de los astrocitos?", "ops": ["Con el capilar: sus pies lo rodean por fuera", "Con la cavidad del ventrículo: la tapizan por dentro", "Con la mielina: la fabrican en la sustancia blanca", "Con la microglía: la envuelven para que no se mueva"], "ok": 0, "pista": "Mira qué toca el astrocito protoplasmático en la parte de arriba.", "exp": "Los pies perivasculares cubren casi todo el contorno de los capilares: así el astrocito queda entre la sangre y la neurona."}, {"p": "Las células ependimarias forman una fila continua. ¿Hacia dónde apuntan sus cilios?", "ops": ["Hacia la cavidad con líquido (ventrículo o canal central)", "Hacia la sustancia blanca, entre los axones", "Hacia el capilar, para tocar la sangre", "Hacia el soma de la neurona más cercana"], "ok": 0, "pista": "Mira la parte de abajo del esquema.", "exp": "El epéndimo es un epitelio de una capa: su cara con cilios y microvellosidades mira al líquido cefalorraquídeo."}]}]}, {"n": 2, "tipo": "circuito", "titulo": "Glía del SNP en su tejido", "fondo": "img/glia-snp-tejido.jpg", "etiquetas": true, "subtitulo": "La glía del SNP en su tejido", "instrucciones": "A la izquierda, un <strong>ganglio sensitivo</strong>; a la derecha, el <strong>nervio</strong> que sale de él; abajo, un <strong>corte transversal</strong> del nervio. Primero ubica las dos zonas; después elige cada nombre y tócalo en el esquema; al final, responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "zonas", "titulo": "Ganglio y nervio", "ayuda": "Elige un nombre y toca su zona sombreada en el esquema.", "mascara": [{"r": [0, 7, 55, 85], "c": "rgba(124,58,237,.32)"}, {"r": [56, 30, 44, 38], "c": "rgba(13,148,136,.32)"}], "piezas": [{"clave": "ganglio", "nombre": "Ganglio sensitivo", "zona": {"r": [[0, 7, 55.5, 85]]}, "punto": [30, 88], "pista": "Es la zona de los somas redondos y grandes.", "exp": "Agrupación de somas neuronales fuera del SNC (p. ej. el ganglio de la raíz dorsal)."}, {"clave": "nervio", "nombre": "Nervio periférico", "zona": {"r": [[55.5, 30, 44.5, 38]]}, "punto": [75, 66], "pista": "Es la zona de los axones en paralelo, sin somas.", "exp": "Haz de axones que van y vienen del ganglio, envueltos por células de Schwann."}], "preguntas": []}, {"clave": "celulas", "titulo": "Las células", "ayuda": "Elige un nombre y toca su lugar en el esquema (vale cualquier punto de esa estructura).", "piezas": [{"clave": "neurona-g", "nombre": "Soma de neurona", "zona": {"e": [[20.5, 25, 5.8, 8.5], [37, 23.5, 5.5, 8], [48, 29, 3, 4.5], [19.5, 74.5, 6, 9], [35.5, 75.5, 3.8, 5.5], [46.5, 70, 3, 4.5]]}, "punto": [20.5, 25], "pista": "Es el soma violeta grande y redondo (hay seis).", "exp": "Soma de una neurona pseudounipolar: está en el ganglio, fuera del SNC."}, {"clave": "satelite", "nombre": "Célula satélite", "zona": {"e": [[20.5, 25, 7.2, 11], [37, 23.5, 6.8, 10.5], [48, 29, 4.2, 6.5], [19.5, 74.5, 7.3, 11], [35.5, 75.5, 5, 7.5], [46.5, 70, 4.2, 6.5]], "no": {"e": [[20.5, 25, 5.8, 8.5], [37, 23.5, 5.5, 8], [48, 29, 3, 4.5], [19.5, 74.5, 6, 9], [35.5, 75.5, 3.8, 5.5], [46.5, 70, 3, 4.5]]}}, "punto": [12.9, 74.5], "pista": "Son las células aplanadas, color crema, en anillo alrededor de cada soma.", "exp": "Forman una cápsula de una sola capa alrededor de cada soma del ganglio."}, {"clave": "axon", "nombre": "Axón", "zona": {"r": [[18.8, 33, 2.6, 9], [34.9, 33, 2.6, 8], [33.9, 43, 2.6, 5], [45.8, 34, 2.6, 7], [44.9, 43, 2.6, 6], [19.4, 58.5, 2.8, 7], [32, 55, 2.8, 8], [45.4, 58.5, 2.8, 7], [50, 49.5, 7, 6]]}, "punto": [20, 37.5], "pista": "Es la prolongación violeta que sale de un soma y llega hasta las fibras (o los axones delgados sin mielina que se ven entre el ganglio y el nervio).", "exp": "La única prolongación de la neurona pseudounipolar: se divide en T en una rama hacia la raíz dorsal y otra hacia el nervio."}, {"clave": "schwann-m", "nombre": "Célula de Schwann mielinizante", "zona": {"e": [[4.5, 42.3, 4.6, 1.8], [15, 42.3, 4.6, 1.8], [25.5, 42.3, 4.6, 1.8], [36.5, 42.3, 4.6, 1.8], [47, 42.3, 4.6, 1.8], [9, 46.6, 4.4, 1.8], [19.7, 46.6, 4.4, 1.8], [30.5, 46.6, 4.4, 1.8], [41, 46.6, 4.4, 1.8], [51.5, 46.6, 4.4, 1.8], [58.5, 39.1, 4.8, 1.8], [67.3, 39.1, 4.8, 1.8], [78.6, 39.1, 4.8, 1.8], [89, 39.1, 4.8, 1.8], [97.5, 39.1, 4.8, 1.8], [62.3, 44.7, 4.8, 1.8], [72.9, 44.7, 4.8, 1.8], [83, 44.7, 4.8, 1.8], [93, 44.7, 4.8, 1.8], [5, 57.8, 4.6, 1.9], [16, 57.8, 4.6, 1.9], [27, 57.8, 4.6, 1.9], [37.8, 57.8, 4.6, 1.9], [48.4, 57.8, 4.6, 1.9], [58.5, 57.8, 4.6, 1.9], [68.7, 57.8, 4.6, 1.9], [79, 57.8, 4.6, 1.9], [89, 57.8, 4.6, 1.9], [98, 57.8, 4.6, 1.9]]}, "punto": [67.5, 39.8], "pista": "Son los segmentos celestes, uno detrás de otro, a lo largo de un axón.", "exp": "Cada una envuelve un solo tramo (internodo) de un solo axón."}, {"clave": "nodo", "nombre": "Nodo de Ranvier", "zona": {"e": [[9.8, 42.3, 1.4, 2], [20, 42.4, 1.4, 2], [31.2, 42.3, 1.4, 2], [41.7, 42.3, 1.4, 2], [52.2, 42.3, 1.4, 2], [4.1, 45.7, 1.4, 2], [14.1, 46.6, 1.4, 2], [25.3, 46.6, 1.4, 2], [35.6, 46.7, 1.4, 2], [46.2, 46.7, 1.4, 2], [57.2, 45.5, 1.4, 2], [10.6, 57.8, 1.4, 2], [21.2, 57.8, 1.4, 2], [32.5, 57.8, 1.4, 2], [43.2, 57.8, 1.4, 2], [53.5, 57.8, 1.4, 2], [62, 39, 1.4, 2], [72.5, 39, 1.4, 2], [84.8, 39, 1.4, 2], [93.5, 39, 1.4, 2], [67.6, 44.6, 1.4, 2], [78.2, 44.6, 1.4, 2], [87.8, 44.6, 1.4, 2], [63.4, 58, 1.4, 2], [73.8, 58, 1.4, 2], [83.9, 58, 1.4, 2], [94.2, 58, 1.4, 2]]}, "punto": [41.5, 42.6], "pista": "Es el tramo corto, violeta, entre dos células de Schwann.", "exp": "Tramo de axón sin mielina entre dos células de Schwann. La T de la neurona del ganglio se divide en un nodo."}, {"clave": "schwann-nm", "nombre": "Célula de Schwann no mielinizante", "zona": {"e": [[17.5, 51.5, 6.5, 2.6], [31, 51.5, 6, 2.6], [44.5, 51.5, 6, 2.6], [66.5, 53.8, 6, 2.6], [79.5, 53.8, 6, 2.6], [92, 53.8, 6, 2.6], [4.5, 51, 4, 2.6]]}, "punto": [66.5, 53.8], "pista": "Son las células celestes alargadas y translúcidas con varios axones delgados dentro.", "exp": "Envuelve varios axones delgados sin formar capas de mielina (fibra de Remak)."}, {"clave": "capilar", "nombre": "Capilar", "zona": {"e": [[85, 62, 15.5, 2.2]]}, "punto": [80, 62], "pista": "Es el vaso con glóbulos rojos dentro del nervio.", "exp": "Vaso sanguíneo del endoneuro que irriga el nervio."}, {"clave": "conectivo", "nombre": "Tejido conectivo", "zona": {"r": [[56, 31.5, 44, 3.8], [56, 64.5, 44, 3], [24, 83, 18, 4], [26, 11, 18, 4]]}, "punto": [75, 33.5], "pista": "Es el tejido rosado y fibroso que rodea al ganglio y al nervio.", "exp": "Cápsula del ganglio y envolturas del nervio: sostienen y protegen a neuronas y glía."}], "preguntas": [{"p": "En el ganglio, ¿cómo se relacionan los somas vecinos?", "ops": ["Cada soma tiene su propia cápsula de células satélite y no toca a los otros", "Los somas se tocan directamente y se unen por sinapsis entre ellos", "Una sola célula satélite envuelve a varios somas a la vez", "Los somas están sueltos en el tejido conectivo, sin glía alrededor"], "ok": 0, "pista": "Mira el anillo color crema de cada soma.", "exp": "En el ganglio cada soma queda dentro de su propia cápsula de células satélite: no hay contacto directo entre somas vecinos."}, {"p": "Compara la célula de Schwann mielinizante con el oligodendrocito del nivel I. ¿Qué cambia?", "ops": ["Cada Schwann envuelve un solo tramo de un axón; el oligodendrocito, tramos de varios axones", "La Schwann envuelve varios axones; el oligodendrocito, un solo tramo de un axón", "La Schwann no forma mielina; sólo el oligodendrocito la forma", "Son la misma célula: cambia el nombre según el lugar del cuerpo"], "ok": 0, "pista": "Cuenta cuántas células de Schwann hay a lo largo de un mismo axón.", "exp": "SNP: una célula de Schwann = un internodo de un axón (un axón largo necesita cientos en fila). SNC: un oligodendrocito = internodos de muchos axones."}, {"p": "En el corte transversal (círculo de abajo), ¿qué diferencia a la célula de Schwann no mielinizante de las mielinizantes?", "ops": ["Aloja varios axones delgados hundidos en su citoplasma, sin anillos de mielina", "Aloja un solo axón grueso rodeado de muchos anillos de mielina", "No tiene núcleo, a diferencia de las mielinizantes", "Está dentro del capilar, junto a los glóbulos rojos"], "ok": 0, "pista": "Busca en el círculo la célula con varios axones pequeños y sin anillos.", "exp": "Es una fibra de Remak: una Schwann aloja varios axones delgados (como los del dolor lento) sin mielinizarlos. Las mielinizantes se ven como anillos concéntricos alrededor de un solo axón."}]}]}, {"n": 3, "tipo": "practica", "titulo": "¿Quién es quién? Forma y lugar"}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (3, 10, 3, '¿Quién es quién? Forma y lugar', 'Lee la descripción y toca la tarjeta de la célula. Cada acierto escribe una celda del cuadro: primero la <strong>forma</strong>, después <strong>dónde está</strong>. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (3, 'Cuerpo pequeño y alargado, con ramas finas y espinosas que se mueven por el tejido.', 'Microglía', 'microglia',
      'Es la más pequeña de la glía del SNC.',
      'Sus ramas exploran el tejido todo el tiempo, aunque no haya daño.', 1, 'Forma', 'Pequeña, ramas finas y espinosas', NULL, NULL),
  (3, 'Forma de estrella: muchas prolongaciones que terminan en pies ensanchados.', 'Astrocito', 'astrocitos',
      'Su nombre significa «célula estrella».',
      'Sus pies se apoyan en capilares, sinapsis y nodos.', 2, 'Forma', 'Estrella con pies', NULL, NULL),
  (3, 'Cuerpo pequeño y redondo con varias prolongaciones; cada una se aplana y se enrolla en un axón distinto.', 'Oligodendrocito', 'oligodendrocitos',
      'Una sola célula del SNC forma mielina en muchos axones a la vez.',
      'Cada prolongación forma un internodo de mielina: una sola célula puede mielinizar hasta unos 50 axones.', 3, 'Forma', 'Varias ramas, cada una a un axón', NULL, NULL),
  (3, 'Cúbica o cilíndrica, con cilios, unida a sus vecinas en una sola capa.', 'Célula ependimaria', 'ependimaria|ependimarias',
      'Es la única glía con forma de epitelio.',
      'Forma el epéndimo, un epitelio cúbico simple.', 4, 'Forma', 'Epitelio cúbico con cilios', NULL, NULL),
  (3, 'Se enrolla muchas veces alrededor de un solo tramo de un axón.', 'Célula de Schwann', 'schwann|celula de schwann',
      'Una célula, un tramo, un axón.',
      'Un axón largo necesita cientos de ellas en fila.', 5, 'Forma', 'Se enrolla en 1 tramo de 1 axón', NULL, NULL),
  (3, 'Pequeña y aplanada; junto a otras forma un anillo alrededor de un soma.', 'Célula satélite', 'satelite|satelites',
      'Piensa en el anillo color crema del nivel II.',
      'Varias células satélite forman la cápsula de cada soma.', 6, 'Forma', 'Aplanada, en anillo', NULL, NULL),
  (3, 'Tapiza los ventrículos del encéfalo y el canal central de la médula.', 'Célula ependimaria', 'ependimaria|ependimarias',
      'Busca la glía que reviste cavidades con líquido.',
      'Está en contacto con el líquido cefalorraquídeo.', 7, 'Dónde está', 'Ventrículos y canal central', NULL, NULL),
  (3, 'Rodea el soma de cada neurona en los ganglios sensitivos y autonómicos.', 'Célula satélite', 'satelite|satelites',
      'Estás fuera del SNC, en un ganglio.',
      'Es glía del SNP. Rodea a las neuronas pseudounipolares de los ganglios sensitivos y también a las multipolares de los ganglios autónomos (simpáticos y parasimpáticos).', 8, 'Dónde está', 'Ganglios (SNP)', NULL, NULL),
  (3, 'En el SNC, sobre todo en la sustancia blanca, en hileras entre los axones.', 'Oligodendrocito', 'oligodendrocitos',
      'Busca la glía que acompaña a los axones dentro del SNC.',
      'Sus núcleos se ven en hileras entre las fibras.', 9, 'Dónde está', 'Sustancia blanca (SNC)', NULL, NULL),
  (3, 'En la sustancia gris y en la blanca; sus pies cubren los capilares.', 'Astrocito', 'astrocitos',
      'Hay un tipo en cada sustancia.',
      'Protoplasmático en la gris y fibroso en la blanca.', 10, 'Dónde está', 'Gris y blanca (SNC)', NULL, NULL),
  (3, 'A lo largo de los axones de los nervios, desde la raíz hasta el músculo.', 'Célula de Schwann', 'schwann|celula de schwann',
      'Estás en el nervio periférico.',
      'Es glía del SNP.', 11, 'Dónde está', 'Nervios (SNP)', NULL, NULL),
  (3, 'Repartida de forma pareja por todo el SNC: cada célula vigila su propia zona, sin superponerse con sus vecinas. Es la única glía que no nace del tejido nervioso.', 'Microglía', 'microglia',
      'Piensa en la glía de defensa: nace de los mismos precursores que los macrófagos de la sangre.',
      'Nace del mesodermo (precursores inmunes) y entra al SNC durante el desarrollo.', 12, 'Dónde está', 'Todo el SNC · origen inmune', NULL, NULL);

-- Actividad 11: LA GLÍA EN EL TEJIDO (práctico 2). Niveles I-III capturas en láminas reales (médula H&E, médula cresil, ganglio y nervio); nivel IV práctica «elegir» con imágenes de inmunofluorescencia de Wikimedia Commons (img/glia-if/, con autor y licencia en el pie)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (11, 7, 'glia-tejido', 'La glía en el tejido',
       'Encuentra la glía en cortes reales. Nivel I: el canal central y la sustancia blanca de la médula. Nivel II: la motoneurona y la glía que la rodea. Nivel III: las células satélite del ganglio y las envolturas del nervio.',
       'lamina', 1, 'Reconocer la glía del SNC y del SNP en cortes reales por su forma, su ubicación y lo que la rodea.', 'Buscar, capturar, recortar, etiquetar y responder en láminas reales.', 'Clase Células del sistema nervioso II 2026 · MHS-240, UCSF-163, MH-051 y MH-052 (histologyguide.com)');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (11, 'tareas', '{"laminas": {"mhs240": {"nombre": "H&E (conejo)", "url": "https://histologyguide.com/slideview/MHS-240-spinal-cord/06-slide-1.html?x=8910&y=6975&z=5.786", "caption": "Médula espinal de conejo — H&E (histologyguide.com)"}, "ucsf163": {"nombre": "Cresil violeta (gato)", "url": "https://histologyguide.com/slideview/UCSF-163-spinal-cord/06-slide-1.html?x=12976&y=9803&z=4.400", "caption": "Médula espinal de gato — cresil violeta (histologyguide.com)"}, "mh051": {"nombre": "Azan (ganglio)", "url": "https://histologyguide.com/slideview/MH-051-dorsal-root-ganglion/06-slide-1.html?x=8730&y=6571&z=6.082", "caption": "Ganglio de la raíz dorsal — Azan (histologyguide.com)"}, "mh052": {"nombre": "H&E (nervio)", "url": "https://histologyguide.com/slideview/MH-052-peripheral-nerve/06-slide-1.html?x=18642&y=16157&z=4.930", "caption": "Nervio periférico — H&E (histologyguide.com)"}}, "niveles": [{"n": 1, "tipo": "capturas", "titulo": "Canal central y sustancia blanca", "laminas": ["mhs240"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "canal-central", "objeto": "la zona", "titulo": "Canal central", "lamina": "mhs240", "busca": "Acércate al centro de la médula, donde se cruzan las astas de la sustancia gris: busca un pequeño orificio y acércate hasta ver las células que forman su borde.", "etiquetas": ["Canal central", "Células ependimarias", "Sustancia gris"], "preguntas": [{"p": "Alrededor del canal central ves una sola capa de células cúbicas, bien juntas. ¿Qué glía es?", "ops": ["Células ependimarias: el epitelio que tapiza el canal central", "Oligodendrocitos en fila que envuelven el borde del canal", "Neuronas pequeñas que rodean la cavidad", "Microglía que se juntó alrededor del canal"], "ok": 0, "pista": "Es la misma fila de células del borde inferior del esquema del nivel I de «Conoce la glía».", "exp": "Es el epéndimo: un epitelio cúbico simple de células ependimarias. Tapiza el canal central de la médula y, más arriba, los ventrículos del encéfalo."}, {"p": "¿En qué parte de la médula está el canal central?", "ops": ["Al centro de la sustancia gris, donde se unen sus dos mitades", "En el borde externo de la sustancia blanca", "Dentro del asta ventral, junto a las motoneuronas", "Fuera de la médula, en la raíz dorsal"], "ok": 0, "pista": "Ubícalo en la vista completa de la lámina, sin zoom.", "exp": "El canal central queda en la comisura gris, al centro de la «H» o «mariposa» de sustancia gris."}]}, {"clave": "sustancia-blanca", "objeto": "la zona", "titulo": "Sustancia blanca", "lamina": "mhs240", "busca": "Desde el centro, baja hacia el borde anterior de la médula, a la zona más clara y sin somas grandes. Acércate hasta ver las fibras cortadas de través (círculos pequeños, cada uno con un punto al centro) y núcleos pequeños y oscuros entre ellas.", "etiquetas": ["Fibra cortada de través", "Núcleo de glía"], "preguntas": [{"p": "En la sustancia blanca ves núcleos pequeños y oscuros entre las fibras. ¿Cómo sabes que no son neuronas?", "ops": ["Son pequeños y no tienen alrededor un soma grande con citoplasma", "Son grandes y claros, con un nucléolo muy marcado", "Están dentro de los axones, donde las neuronas tienen su núcleo", "Se ven rosados, y los núcleos de neurona siempre son morados"], "ok": 0, "pista": "Compáralos con un soma de neurona de la sustancia gris.", "exp": "La neurona tiene un soma grande, con un núcleo claro y un nucléolo visible. En la sustancia blanca casi no hay somas: los núcleos pequeños son de glía."}, {"p": "Las fibras se ven como círculos pequeños, cada uno con un punto rosado al centro y un anillo claro alrededor. ¿Qué es cada parte?", "ops": ["El punto es el axón y el anillo claro es donde estaba la mielina", "El punto es el núcleo de un oligodendrocito y el anillo es su citoplasma", "El punto es un capilar y el anillo claro es su pared", "El punto es la mielina y el anillo claro es el axón vacío"], "ok": 0, "pista": "La mielina es casi toda lípidos: al preparar la lámina con alcohol, los lípidos se disuelven.", "exp": "En este corte las fibras vienen hacia ti: el axón queda como un punto y la mielina, que se disolvió al procesar el tejido, deja un anillo claro. Los núcleos pequeños y oscuros entre las fibras son sobre todo de oligodendrocitos, que forman esa mielina."}]}]}, {"n": 2, "tipo": "capturas", "titulo": "Motoneurona y su glía", "laminas": ["ucsf163"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "motoneurona", "titulo": "Motoneurona del asta ventral", "lamina": "ucsf163", "busca": "En la parte ancha y anterior de la sustancia gris, busca el soma más grande que encuentres y acércate hasta ver su núcleo, sus prolongaciones y lo que lo rodea.", "etiquetas": ["Soma", "Núcleo", "Prolongación", "Núcleos de glía", "Neuropilo"], "preguntas": [{"p": "Alrededor del soma de la motoneurona ves varios núcleos pequeños pegados a su borde. ¿Qué son?", "ops": ["Núcleos de glía que rodean a la neurona (glía perineuronal)", "Núcleos extra de la motoneurona, que tiene varios", "Botones terminales de otras neuronas, teñidos de violeta", "Células de Schwann que forman mielina sobre el soma"], "ok": 0, "pista": "¿Una neurona tiene uno o varios núcleos? ¿Qué células acompañan a las neuronas en el SNC?", "exp": "Son núcleos de glía, sobre todo oligodendrocitos y astrocitos perineuronales. La motoneurona tiene un solo núcleo, grande y claro. Las células de Schwann sólo están en el SNP."}, {"p": "Compara estos núcleos de glía con los de la sustancia blanca del nivel I. ¿Qué cambió?", "ops": ["Su ubicación: aquí rodean un soma; allá van dispersos entre las fibras", "Su tamaño: aquí son tan grandes como el núcleo de la neurona", "Su número: aquí no hay glía, sólo neuronas", "Nada: en la sustancia gris no hay núcleos de glía"], "ok": 0, "pista": "Piensa en qué acompaña la glía en cada zona.", "exp": "La misma glía del SNC se ubica según lo que acompaña: junto a somas en la sustancia gris (perineuronal) y entre los axones que mieliniza en la sustancia blanca."}, {"p": "Entre los somas hay un fondo con pocos núcleos (neuropilo). ¿De qué está formado?", "ops": ["Dendritas, axones y prolongaciones de glía que se entrelazan", "Líquido cefalorraquídeo que se coaguló al fijar el tejido", "Mielina de la sustancia blanca que se mezcla con la gris", "Somas pequeños que el colorante no alcanzó a teñir"], "ok": 0, "pista": "Entre somas y núcleos, ¿qué otras partes de las células quedan?", "exp": "El neuropilo es la red de dendritas, axones, sinapsis y prolongaciones de astrocitos y microglía. Ahí ocurre la mayoría de las sinapsis de la sustancia gris."}]}]}, {"n": 3, "tipo": "capturas", "titulo": "Ganglio y nervio periférico", "laminas": ["mh051", "mh052"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "ganglio", "titulo": "Neurona del ganglio", "lamina": "mh051", "busca": "Busca los somas grandes y redondos agrupados entre haces de fibras; acércate a uno hasta ver qué lo rodea.", "etiquetas": ["Soma neuronal", "Núcleo", "Células satélite", "Haz de fibras"], "preguntas": [{"p": "Cada soma del ganglio tiene un anillo de núcleos pequeños, como la motoneurona del nivel II. ¿Cuál es la diferencia?", "ops": ["Aquí son células satélite y estás fuera del SNC, en un ganglio", "Aquí son oligodendrocitos, igual que alrededor de la motoneurona", "Aquí son células de Schwann que forman mielina sobre el soma", "Aquí son fibroblastos de la cápsula que envuelve todo el ganglio"], "ok": 0, "pista": "¿Este corte es del SNC o del SNP? ¿Qué glía corresponde a cada uno?", "exp": "En el ganglio cada soma está envuelto por células satélite (SNP). Alrededor de la motoneurona (SNC) la glía es oligodendrocitos y astrocitos. Los dos se ven como un anillo de núcleos: lo que cambia es dónde estás."}, {"p": "Los somas del ganglio se ven redondos y casi sin prolongaciones, a diferencia de la motoneurona. ¿Por qué?", "ops": ["Son pseudounipolares: su única prolongación rara vez queda en el corte", "Son neuronas inmaduras que todavía no forman dendritas ni axón", "Sí tienen muchas ramas, pero la tinción sólo muestra el soma", "Son células gliales grandes, no neuronas, y por eso no tienen ramas"], "ok": 0, "pista": "Recuerda cuántas prolongaciones salen del soma de una neurona del ganglio de la raíz dorsal.", "exp": "Del soma de la neurona pseudounipolar sale una sola prolongación, que luego se divide en T. Como es una sola, pocas veces queda en el plano del corte."}]}, {"clave": "nervio", "objeto": "la zona", "titulo": "Nervio en corte transversal", "lamina": "mh052", "busca": "Mira las envolturas del nervio entero, de cada grupo de fibras (fascículo) y de cada fibra. Acércate a un fascículo hasta ver círculos claros con un punto al centro.", "etiquetas": ["Epineuro", "Perineuro", "Fascículo", "Endoneuro", "Fibra mielinizada"], "preguntas": [{"p": "Cada fibra mielinizada se ve como un círculo claro con un punto al centro. ¿Qué es cada parte?", "ops": ["El punto es el axón y el halo claro es el lugar que ocupa la mielina", "El punto es el núcleo de Schwann y el halo, su citoplasma", "El punto es un capilar y el halo, la sangre que lo rodea", "El punto es la mielina y el halo, el axón hinchado"], "ok": 0, "pista": "¿Qué va al centro de una fibra mielinizada y qué la envuelve?", "exp": "El axón queda al centro y la mielina lo rodea; al procesar el tejido sus lípidos se pierden y queda un halo claro."}, {"p": "En el corte ves núcleos grandes pegados a un axón y otros pequeños entre las fibras. ¿De qué células son?", "ops": ["Los grandes, de células de Schwann; los pequeños, de fibroblastos", "Los grandes, de fibroblastos; los pequeños, de células de Schwann", "Los grandes, de neuronas; los pequeños, de células de Schwann", "Los grandes, de oligodendrocitos; los pequeños, de fibroblastos"], "ok": 0, "pista": "En un nervio no hay somas de neuronas. ¿Qué célula va pegada a cada axón?", "exp": "El núcleo de la célula de Schwann queda al lado del axón que envuelve. Los pequeños son de fibroblastos del endoneuro. En un nervio no hay somas neuronales y los oligodendrocitos están en el SNC."}, {"p": "¿Qué envoltura rodea a cada grupo de fibras (fascículo)?", "ops": ["El perineuro", "El epineuro", "El endoneuro", "La mielina"], "ok": 0, "pista": "Epi = sobre todo el nervio; peri = alrededor del fascículo; endo = dentro, en cada fibra.", "exp": "Epineuro: todo el nervio. Perineuro: cada fascículo (sus células unidas forman la barrera hemato-nerviosa). Endoneuro: cada fibra."}]}]}]}', NULL, 1);
-- Actividad 14: GLÍA CON ANTICUERPOS (fuera de la ruta desde la sesión 10; queda en el pool, en desarrollo). Era el nivel IV de «La glía en el tejido»
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente, estado) VALUES
  (14, 7, 'glia-anticuerpos', 'Glía con anticuerpos',
       'Reconoce cada glía en imágenes reales de inmunofluorescencia e inmunohistoquímica por su forma y su lugar.',
       'practica', 1, 'Reconocer la glía por su forma y su ubicación en imágenes con anticuerpos.', 'Mirar cada imagen y tocar la tarjeta de la célula marcada.', 'Wikimedia Commons (autor y licencia en el pie de cada imagen)', 'en_desarrollo');
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (5, 14, 1, 'Glía con anticuerpos', 'Cada imagen es real: un anticuerpo se une a una proteína de una célula y la pinta de un color. Mira la <strong>forma</strong> y el <strong>lugar</strong> de lo marcado y toca la tarjeta de la célula; el pie de la imagen dice qué marca cada color. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (5, 'Cultivo de células nerviosas. Mira la forma de la célula amarilla: un cuerpo central con muchas prolongaciones largas, como una estrella. ¿Qué célula es?', 'Astrocito', 'astrocitos|astroglia',
      'Su nombre significa «célula estrella».',
      'El anticuerpo marca GFAP, un filamento intermedio propio de los astrocitos: por eso con él se ven completos.', 1, NULL, NULL, NULL, '{"img": "img/glia-if/astrocito-gfap.jpg", "pie": "GFAP (amarillo) · núcleos (azul). GerryShaw, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'Tejido cerebral con dos marcas: los tubos magenta son vasos sanguíneos y lo verde es una glía. Sus prolongaciones llegan a los vasos y los forran por fuera. ¿Qué célula forma esos pies alrededor del vaso?', 'Astrocito', 'astrocitos|astroglia',
      'Busca la glía que se ubica entre el vaso y la neurona.',
      'Son los pies perivasculares de los astrocitos (marcados con GFAP), como en el esquema del nivel I de «Conoce la glía».', 2, NULL, NULL, NULL, '{"img": "img/glia-if/astrocitos-vasos-gfap.jpg", "pie": "GFAP (verde) · vasos sanguíneos (magenta). Jeffery J. Iliff, dominio público, Wikimedia Commons"}'),
  (5, 'Cultivo mixto de encéfalo. Las células verdes son pequeñas, de cuerpo compacto, y están entre prolongaciones rojas muy largas. ¿Qué son las verdes?', 'Microglía', 'microglia|microglias',
      'Es la glía más pequeña.',
      'Marcadas con coronina 1a, una proteína de la actina que la microglía usa para moverse y fagocitar.', 3, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-neuronas.jpg", "pie": "Coronina 1a (verde) · α-internexina (rojo). GerryShaw / EnCor, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'En la misma imagen, las prolongaciones rojas son larguísimas y forman una red. ¿De qué células son?', 'Neurona', 'neuronas',
      'No todo lo que se marca es glía: ¿qué célula tiene prolongaciones tan largas?',
      'Están marcadas con α-internexina, un neurofilamento: el filamento intermedio de las neuronas (el de los astrocitos es GFAP).', 4, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-neuronas.jpg", "pie": "Coronina 1a (verde) · α-internexina (rojo). GerryShaw / EnCor, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'Encéfalo de ratón. La célula verde tiene pocas prolongaciones que corren paralelas, cada una hacia una fibra distinta. ¿Qué célula es?', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Pocas ramas, muchos axones, dentro del SNC.',
      'El anticuerpo Rip marca oligodendrocitos y su mielina: cada prolongación forma un internodo en un axón distinto.', 5, NULL, NULL, NULL, '{"img": "img/glia-if/oligodendrocito-rip.jpg", "pie": "Rip (verde) · núcleos Hoechst (azul). O. Tsupykov, CC BY-SA 4.0, Wikimedia Commons"}'),
  (5, 'Nervio ciático de rata. Lo rojo envuelve, uno por uno, a los axones del nervio. ¿Qué célula es?', 'Célula de Schwann', 'schwann|celulas de schwann',
      'Estás en el SNP, a lo largo de los axones.',
      'S100 (rojo) marca el citoplasma de las células de Schwann; MBP (verde) marca la mielina que forman.', 6, NULL, NULL, NULL, '{"img": "img/glia-if/schwann-mbp-s100.jpg", "pie": "MBP (verde) · S100 (rojo) · núcleos (celeste). V. Ustymenko, CC BY 4.0, Wikimedia Commons"}'),
  (5, 'Ganglio de la raíz dorsal humano (panel A, normal). Una envoltura café, delgada, rodea a cada soma neuronal. ¿Qué glía forma esa cápsula?', 'Célula satélite', 'satelite|satelites',
      'Es la glía de los ganglios, alrededor de los somas.',
      'La laminina marca la lámina basal de las células satélite. En B (ataxia de Friedreich) la cápsula se engruesa en capas.', 7, NULL, NULL, NULL, '{"img": "img/glia-if/satelite-laminina.jpg", "pie": "Laminina, inmunohistoquímica (café). A: normal; B: ataxia de Friedreich. Koeppen et al. en Hanani, CC BY 4.0, Wikimedia Commons"}');

-- Esquemas de glía (tarea B, Kaira Santos): img/glia-snc.jpg y img/glia-snp.jpg (desde la sesión 08, Conoce la glía usa img/glia-snc-tejido.jpg e img/glia-snp-v2.jpg con zonas en el recurso «tareas»).

-- Actividad 13: LA GLÍA EN ACCIÓN (práctico 2) · FUNCIÓN. I la unidad neurovascular en acción («escenas», modo «poe»: 4 situaciones,
-- predice → mira la animación → explicación; vb 1536×1024); II ¿qué cruza la barrera? (práctica «elegir», practica_niveles numero 2);
-- III cuando se ataca la mielina («escenas», modo «casos»: 4 enfermedades con imagen real, SNC o SNP → célula → por qué,
-- y cuadro comparativo); IV la lesión en el SNP y el SNC («escenas», modo «etapas»: la secuencia se destapa y anima por etapas,
-- luego 10 hechos → solo SNP / solo SNC / en ambos en el panel y cuadro por etapa); V glía que cambia: estados funcionales (práctica «elegir», numero 5, imágenes en miniatura)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (13, 7, 'glia-accion', 'La glía en acción',
       'Lo que la glía hace y cómo responde. Nivel I: la unidad neurovascular en reposo, en actividad, en un ACV y con la barrera abierta. Nivel II: qué cruza la barrera hematoencefálica. Nivel III: cuatro pacientes con la mielina dañada. Nivel IV: qué pasa tras cortar un axón en el SNP y en el SNC. Nivel V: los estados de la glía en la lesión, el desarrollo y la enfermedad.',
       'lamina', 1, 'Explicar las funciones de la glía (barrera, sinapsis tripartita, metabolismo, mielina) y su respuesta a la lesión, la regeneración y la enfermedad.', 'Predecir y mirar animaciones de la unidad neurovascular; resolver casos clínicos de mielina dañada; clasificar sustancias según la barrera; comparar la lesión en el SNP y el SNC en un cuadro; reconocer estados de la glía en casos e imágenes reales.', 'Clase Células del sistema nervioso II y Neurogénesis y neuroplasticidad III 2026 · esquemas de Fernanda López');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (13, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "escenas", "modo": "poe", "titulo": "La unidad neurovascular en acción", "subtitulo": "Cuatro escenas: predice y mira", "fondo": "img/glia-accion/neurovascular.jpg", "vb": [1536, 1024], "alt": "Capilar, astrocito y sinapsis", "instrucciones": "La misma unidad neurovascular en <strong>cuatro situaciones</strong>. En cada una: lee la situación y <strong>predice</strong> qué va a pasar (una sola oportunidad); después <strong>mira</strong> la animación y lee la explicación. Con «Nombres» ves cada estructura. <strong>Verde</strong>: predijiste bien. <strong>Rojo</strong>: por repasar.", "nombres": [{"x": 280, "y": 445, "t": "Sangre"}, {"x": 110, "y": 520, "t": "Célula endotelial"}, {"x": 190, "y": 640, "t": "Unión estrecha"}, {"x": 380, "y": 285, "t": "Pericito"}, {"x": 505, "y": 610, "t": "Pie astrocitario"}, {"x": 812, "y": 480, "t": "Astrocito"}, {"x": 1300, "y": 330, "t": "Terminal presináptico", "i": 1}, {"x": 1188, "y": 415, "t": "Prolongación perisináptica", "i": 1}, {"x": 1300, "y": 552, "t": "Hendidura", "i": 1}, {"x": 1330, "y": 690, "t": "Espina dendrítica", "i": 1}], "guia_img": "La unidad neurovascular", "guia_pie": "Capilar con su barrera, astrocito y sinapsis tripartita.", "casos": [{"clave": "normal", "titulo": "Un día cualquiera", "corto": "Normal", "situacion": "Tu encéfalo trabaja en reposo: la sangre trae glucosa y la sinapsis libera glutamato cada vez que pasa una señal.", "pasos": [{"tipo": "predice", "p": "La glucosa tiene que salir de la sangre hacia el tejido nervioso. ¿Por dónde cruza?", "ops": ["Atraviesa las células endoteliales por un transportador (GLUT1)", "Pasa por los espacios entre las células endoteliales", "La lleva el glóbulo rojo hasta la neurona", "No cruza: el encéfalo se alimenta solo de grasas"], "ok": 0}], "anim": {"flujos": [{"d": "M250 520 Q330 495 430 470 L505 460 Q650 440 790 468", "f": "glu", "n": 6, "dur": 4}, {"d": "M835 468 Q960 440 1100 425 Q1160 428 1185 450 Q1215 470 1255 470", "f": "lac", "n": 5, "dur": 3.5, "t": 1}, {"d": "M1280 495 L1290 550 Q1240 556 1195 545", "f": "glut", "n": 3, "dur": 2.4, "t": 1.5}, {"d": "M1360 495 L1360 552 Q1405 556 1448 545", "f": "glut", "n": 3, "dur": 2.4, "t": 1.8}, {"d": "M1320 500 L1320 552 L1322 580", "f": "glut", "n": 2, "dur": 2, "t": 2}, {"d": "M1190 535 Q1185 485 1240 472", "f": "gln", "n": 3, "dur": 2, "t": 2.6}], "rotulos": [{"x": 430, "y": 470, "t": "1 · Cruza el endotelio (GLUT1)", "s": 0.3, "i": 1}, {"x": 510, "y": 525, "t": "2 · La recibe el pie astrocitario", "s": 1.1}, {"x": 790, "y": 385, "t": "3 · Glucosa → lactato", "s": 2}, {"x": 1250, "y": 455, "t": "4 · Lactato para la neurona", "s": 3, "i": 1}, {"x": 1190, "y": 600, "t": "5 · El astrocito recapta el glutamato", "s": 3.8, "i": 1}, {"x": 1200, "y": 690, "t": "6 · Le devuelve glutamina", "s": 4.6, "i": 1}]}, "exp": "Las uniones estrechas cierran el paso entre células: la glucosa atraviesa el endotelio por GLUT1 (su proteína transportadora), el pie astrocitario la recibe y el astrocito la usa o la convierte en lactato, que entrega a la neurona. Al mismo tiempo retira el glutamato de la sinapsis y se lo devuelve como glutamina para fabricar más."}, {"clave": "actividad", "titulo": "Mañana hay prueba", "corto": "Actividad", "situacion": "Estudias toda la tarde: las neuronas de tu corteza disparan mucho más que en reposo.", "pasos": [{"tipo": "predice", "p": "¿Cómo responde la unidad neurovascular a tanta actividad?", "ops": ["El capilar se dilata y el astrocito entrega más lactato a la neurona", "La barrera se abre para que entre más glucosa entre las células", "La neurona deja de usar glucosa y gasta su propia mielina", "El astrocito guarda toda la glucosa para después y no entrega nada"], "ok": 0}], "anim": {"efectos": [{"e": [270, 490, 214, 214], "c": "rgba(251,146,60,.12)", "s": "#FB923C", "sw": 8, "a": "crece"}], "flujos": [{"d": "M250 520 Q330 495 430 470 L505 460 Q650 440 790 468", "f": "glu", "n": 8, "dur": 2.2}, {"d": "M835 468 Q960 440 1100 425 Q1160 428 1185 450 Q1215 470 1255 470", "f": "lac", "n": 7, "dur": 1.93, "t": 1}, {"d": "M1280 495 L1290 550 Q1240 556 1195 545", "f": "glut", "n": 5, "dur": 1.32, "t": 1.5}, {"d": "M1360 495 L1360 552 Q1405 556 1448 545", "f": "glut", "n": 5, "dur": 1.32, "t": 1.8}, {"d": "M1320 500 L1320 552 L1322 580", "f": "glut", "n": 4, "dur": 1.1, "t": 2}, {"d": "M1190 535 Q1185 485 1240 472", "f": "gln", "n": 5, "dur": 1.1, "t": 2.6}], "rotulos": [{"x": 120, "y": 120, "t": "El capilar se dilata: llega más sangre", "s": 0.3}, {"x": 900, "y": 390, "t": "Más lactato", "s": 1.4}, {"x": 1190, "y": 600, "t": "Más glutamato, recaptado a tiempo", "s": 2.4, "i": 1}]}, "exp": "Acoplamiento neurovascular: con la actividad, astrocitos y pericitos hacen que el capilar se dilate (llega más sangre) y el astrocito entrega más lactato. Ese aumento de flujo es lo que detecta la resonancia magnética funcional cuando un área «se enciende»."}, {"clave": "acv", "titulo": "Se tapa el vaso (ACV)", "corto": "ACV", "situacion": "Un coágulo tapa la arteria que irriga esta zona: deja de llegar sangre con oxígeno y glucosa.", "pasos": [{"tipo": "predice", "p": "El astrocito se queda sin ATP (su energía). ¿Qué pasa primero en la sinapsis?", "ops": ["El glutamato se acumula en la hendidura y sobreexcita a la neurona", "La sinapsis se queda sin glutamato y se apaga sin daño", "El astrocito fabrica más lactato y salva a la neurona", "La mielina se despega del axón"], "ok": 0}], "anim": {"efectos": [{"e": [270, 500, 168, 168], "c": "rgba(40,25,55,.5)"}, {"e": [805, 470, 250, 215], "c": "rgba(110,110,125,.42)", "t": 0.8}, {"e": [1322, 612, 92, 62], "c": "rgba(239,68,68,.38)", "a": "pulso", "t": 3}], "flujos": [{"d": "M1300 495 L1300 548", "f": "glut", "n": 16, "rep": false, "t": 1.4, "paso": 0.22, "dur": 1.1, "fin": [[1240, 551], [1262, 557], [1284, 550], [1306, 558], [1328, 551], [1350, 557], [1372, 550], [1394, 556], [1415, 551], [1252, 546], [1296, 545], [1340, 546], [1384, 545], [1274, 560], [1318, 561], [1362, 560]]}, {"d": "M1290 565 L1296 625", "f": "ca", "n": 3, "dur": 1.6, "t": 3.2}, {"d": "M1352 565 L1346 628", "f": "ca", "n": 3, "dur": 1.6, "t": 3.6}], "rotulos": [{"x": 60, "y": 110, "t": "Sin sangre: sin O₂ ni glucosa", "s": 0.2}, {"x": 700, "y": 650, "t": "Astrocito sin ATP: no recapta", "s": 1}, {"x": 1236, "y": 500, "t": "El glutamato se acumula", "s": 2.2, "i": 1}, {"x": 1250, "y": 745, "t": "Entra Ca²⁺: la neurona se daña", "s": 3.4, "i": 1}]}, "exp": "Excitotoxicidad: sin energía, el astrocito no puede retirar el glutamato; se acumula, abre demasiados receptores, entra Ca²⁺ y se activan enzimas que destruyen la neurona. Por eso el daño de un ACV se extiende durante horas a las neuronas vecinas (penumbra): es la ventana para tratar."}, {"clave": "barrera", "titulo": "La barrera se abre", "corto": "Barrera", "situacion": "Una meningitis (infección de las meninges) inflama los vasos del encéfalo y las uniones estrechas se aflojan.", "pasos": [{"tipo": "predice", "p": "¿Qué le pasa al tejido nervioso?", "ops": ["Entran agua y proteínas de la sangre y el tejido se hincha (edema)", "Nada: el astrocito sella el capilar por sí solo", "Sale la glucosa del encéfalo hacia la sangre", "Las neuronas fabrican nuevas uniones estrechas"], "ok": 0}], "anim": {"efectos": [{"e": [445, 535, 22, 22], "c": "rgba(239,68,68,.3)", "s": "#EF4444", "sw": 4, "a": "pulso"}, {"e": [300, 330, 22, 22], "c": "rgba(239,68,68,.3)", "s": "#EF4444", "sw": 4, "a": "pulso"}, {"e": [100, 432, 22, 22], "c": "rgba(239,68,68,.3)", "s": "#EF4444", "sw": 4, "a": "pulso"}, {"e": [190, 640, 22, 22], "c": "rgba(239,68,68,.3)", "s": "#EF4444", "sw": 4, "a": "pulso"}, {"e": [815, 480, 215, 175], "c": "rgba(125,211,252,.28)", "a": "crece", "t": 2.5}], "flujos": [{"d": "M320 520 Q420 528 447 536 Q520 565 640 600", "f": "agua", "n": 6, "dur": 3}, {"d": "M300 470 Q420 500 447 534 Q540 520 700 520", "f": "prot", "n": 4, "dur": 3.6, "t": 0.6}, {"d": "M290 430 Q296 380 300 332 Q330 260 420 220", "f": "agua", "n": 4, "dur": 3, "t": 0.4}, {"d": "M330 560 Q420 550 447 538 Q560 600 760 640", "f": "prot", "n": 3, "dur": 4, "t": 1.2}], "rotulos": [{"x": 447, "y": 536, "t": "Uniones estrechas abiertas", "s": 0.2}, {"x": 600, "y": 625, "t": "Entran agua y proteínas", "s": 1.2}, {"x": 860, "y": 760, "t": "Edema: el tejido se hincha", "s": 2.6}]}, "exp": "Si las uniones estrechas se abren, el agua y las proteínas del plasma entran al tejido: edema, que sube la presión dentro del cráneo. También pueden entrar células inflamatorias y bacterias. Por eso mismo, algunos antibióticos llegan mejor al encéfalo cuando las meninges están inflamadas."}]}, {"n": 2, "tipo": "practica", "titulo": "¿Qué cruza la barrera?"}, {"n": 3, "tipo": "escenas", "modo": "casos", "dx": true, "titulo": "Cuando se ataca la mielina", "subtitulo": "Cuatro enfermedades y su cuadro comparativo", "instrucciones": "Cuatro enfermedades que dañan la mielina. En cada una, lee el caso y lo que se sabe de la enfermedad, y mira la imagen real (tócala para ampliarla). Luego responde: ¿el daño está en el <strong>SNC o en el SNP</strong>?, ¿qué <strong>célula</strong> es el blanco? y <strong>por qué</strong>. No necesitas saber la enfermedad de memoria: todo lo que necesitas está en el caso y en lo que ya sabes de la glía. Cada caso suma una fila a tu cuadro comparativo. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "cuadro": ["Enfermedad", "SNC o SNP", "Célula blanco", "Causa", "Evolución"], "guia_img": "Los cuatro casos", "guia_pie": "Imágenes reales: J. Heilman (CC BY-SA 4.0); CDC (dominio público); Saied y cols., J Med Case Rep 2021 (CC BY 4.0); Benefros (CC BY-SA 3.0).", "casos": [{"clave": "em", "titulo": "Valentina, 28 años", "corto": "Esclerosis múltiple", "situacion": "Hace una semana ve borroso con el ojo derecho y le duele al moverlo. Hace un año tuvo un hormigueo en una pierna que se pasó solo. El oftalmólogo dice que el ojo está sano: el problema está en el nervio óptico. La resonancia muestra placas en la sustancia blanca del encéfalo.", "contexto": "Enfermedad autoinmune: linfocitos cruzan la barrera hematoencefálica y destruyen mielina. Solo atacan la mielina que forma una célula cuyas prolongaciones envuelven tramos de varios axones a la vez. Por eso las placas aparecen en el encéfalo, la médula espinal y los nervios ópticos, pero nunca en los nervios de brazos y piernas. Avanza en brotes que mejoran en parte.", "foto": "img/glia-accion/casos/em.jpg", "foto_t": "Resonancia del encéfalo (T2), corte horizontal. La flecha marca una placa: una mancha clara en la sustancia blanca, donde se perdió la mielina.", "foto_pie": "James Heilman, MD · CC BY-SA 4.0 · Wikimedia Commons", "pasos": [{"tipo": "sistema", "p": "La visión borrosa viene del nervio óptico. ¿Es parte del SNC o del SNP?", "ops": ["SNC", "SNP"], "ok": 0, "pista": "Aunque se llame «nervio», el nervio óptico es una prolongación del encéfalo. Fíjate también dónde aparecen (y dónde nunca) las placas."}, {"tipo": "tarjeta", "p": "¿Qué célula forma la mielina que se destruye?", "ops": ["Oligodendrocito", "Célula de Schwann", "Astrocito", "Microglía"], "ok": 0, "pista": "Busca la célula del SNC que envuelve varios axones a la vez."}, {"tipo": "elegir", "p": "Una sola placa pequeña deja sin mielina a muchos axones a la vez. ¿Por qué?", "ops": ["Cada oligodendrocito mieliniza tramos de varios axones: si muere, todos pierden ese tramo", "En el SNC los axones no tienen nodos de Ranvier y la mielina es continua en todo el axón", "La mielina del SNC la fabrica la propia neurona y, si se daña, se pierde en todo el axón", "Cada célula de Schwann cubre con su mielina muchos axones a la vez, como un manojo"], "ok": 0, "pista": "Recuerda cuántos axones envuelve una sola célula mielinizante del SNC."}], "exp": "Esclerosis múltiple: enfermedad autoinmune del SNC. Linfocitos y anticuerpos cruzan la barrera y destruyen la mielina del oligodendrocito (sus proteínas MBP, PLP y MOG). Como cada oligodendrocito mieliniza varios axones, una placa afecta a muchos a la vez. Las placas aparecen en distintos lugares y momentos (brotes); los precursores NG2 remielinizan en parte, con mielina más delgada.", "fila": ["SNC: nervio óptico, encéfalo, médula", "Oligodendrocito (mielina de varios axones)", "Autoinmune", "Brotes; se recupera en parte"], "img": "img/glia-if/oligodendrocito-rip.jpg", "ctx": "Así se ve un oligodendrocito real (verde), con prolongaciones hacia varios axones. En la esclerosis múltiple, esta mielina es la que se destruye.", "pie": "Rip (verde) · núcleos Hoechst (azul). O. Tsupykov, CC BY-SA 4.0, Wikimedia Commons", "img_t": "Ver la célula real"}, {"clave": "gb", "titulo": "Jorge, 45 años", "corto": "Guillain-Barré", "situacion": "Dos semanas después de una diarrea por la bacteria Campylobacter siente hormigueo en los pies y una debilidad que sube en pocos días hasta los brazos. No tiene reflejos y le cuesta tragar. La resonancia del encéfalo y de la médula es normal; el estudio de sus nervios muestra que conducen muy lento.", "contexto": "Síndrome autoinmune que aparece días o semanas después de una infección. Campylobacter tiene en su superficie azúcares casi idénticos a los gangliósidos (lípidos de membrana) de la mielina de los nervios. Los anticuerpos que el cuerpo fabrica contra la bacteria también se pegan a esa mielina. Afecta primero a los nervios más largos. La mayoría se recupera en semanas a meses.", "foto": "img/glia-accion/casos/gb.jpg", "foto_t": "Campylobacter jejuni al microscopio electrónico de barrido: una bacteria en espiral de unos 2 a 3 µm. Es la misma especie que le causó la diarrea a Jorge.", "foto_pie": "CDC / P. Fields y C. Fitzgerald (PHIL 5781) · Dominio público · Wikimedia Commons", "pasos": [{"tipo": "sistema", "p": "¿Dónde está el daño: en el SNC o en el SNP?", "ops": ["SNC", "SNP"], "ok": 1, "pista": "La resonancia del encéfalo y la médula es normal, y la debilidad empieza en los pies: piensa en los nervios más largos."}, {"tipo": "tarjeta", "p": "¿Qué célula forma la mielina dañada?", "ops": ["Oligodendrocito", "Célula de Schwann", "Astrocito", "Microglía"], "ok": 1, "pista": "Estás en el SNP."}, {"tipo": "elegir", "p": "¿Por qué una infección intestinal termina atacando los nervios?", "ops": ["Los anticuerpos contra la bacteria reconocen moléculas parecidas en la mielina del nervio", "La bacteria viaja por la sangre hasta los nervios y se alimenta de su mielina", "La diarrea deshidrata los nervios y la mielina se despega del axón", "Los antibióticos usados contra la diarrea destruyen a las células de Schwann"], "ok": 0, "pista": "El problema no es la bacteria en sí, sino la respuesta inmune contra ella: relee «Sobre la enfermedad»."}], "exp": "Síndrome de Guillain-Barré: autoinmune del SNP tras una infección. Por mimetismo molecular, los anticuerpos contra la bacteria dañan la mielina de la célula de Schwann (o el axón, en otras formas). La mayoría se recupera en semanas a meses porque la célula de Schwann remieliniza; en la fase aguda puede necesitar apoyo para respirar o tragar.", "fila": ["SNP: raíces y nervios", "Célula de Schwann (su mielina)", "Autoinmune, tras una infección", "Suele recuperarse en meses"], "img": "img/glia-if/schwann-mbp-s100.jpg", "ctx": "Nervio periférico real: en rojo, las células de Schwann (S100); en verde, la mielina que forman (MBP). En Guillain-Barré, esta mielina es el blanco.", "pie": "MBP (verde) · S100 (rojo) · núcleos (celeste). V. Ustymenko, CC BY 4.0, Wikimedia Commons", "img_t": "Ver la célula real"}, {"clave": "nmo", "titulo": "Matías, 29 años", "corto": "Neuromielitis óptica", "situacion": "Pierde casi toda la visión del ojo derecho y, días después, se le debilitan las dos piernas hasta no poder caminar y no logra orinar. La resonancia de la columna muestra una lesión muy larga dentro de la médula espinal (flechas). En su sangre hay anticuerpos contra la acuaporina-4.", "contexto": "Enfermedad autoinmune distinta de la esclerosis múltiple. Los anticuerpos atacan la acuaporina-4, un canal de agua que está en los pies que rodean los capilares del encéfalo, la médula y el nervio óptico. Ni las neuronas ni la mielina tienen acuaporina-4, pero igual se pierde la mielina de la zona. Sus lesiones de la médula son largas: tres o más segmentos.", "foto": "img/glia-accion/casos/nmo.jpg", "foto_t": "Resonancia de la columna (T2), vista de perfil. Las flechas marcan una lesión clara y larga dentro de la médula espinal, desde el cuello (C5) hasta la mitad de la espalda (T10).", "foto_pie": "Saied Z. y cols., J Med Case Rep 2021;15:391 · CC BY 4.0", "pasos": [{"tipo": "sistema", "p": "La debilidad de las piernas y la orina: ¿el daño está en el SNC o en el SNP?", "ops": ["SNC", "SNP"], "ok": 0, "pista": "Mira la resonancia: la lesión está dentro de la médula espinal."}, {"tipo": "tarjeta", "p": "¿Qué célula tiene la acuaporina-4 y es el blanco del ataque?", "ops": ["Oligodendrocito", "Célula de Schwann", "Astrocito", "Microglía"], "ok": 2, "pista": "¿Qué célula cubre los capilares con sus pies? Lo viste en el nivel I."}, {"tipo": "elegir", "p": "Si el ataque no es contra la mielina, ¿por qué se pierde mielina?", "ops": ["Sin astrocitos sanos, los oligodendrocitos pierden su apoyo y la inflamación daña la mielina", "Los anticuerpos contra el astrocito también reconocen la proteína P0 de la mielina", "El astrocito se convierte en oligodendrocito y deja de fabricar mielina para los axones", "La mielina no se pierde: solo mueren los somas de las neuronas de la médula espinal"], "ok": 0, "pista": "La glía trabaja en equipo: si cae una, arrastra a las vecinas."}], "exp": "Neuromielitis óptica: los anticuerpos atacan la acuaporina-4 de los pies astrocitarios; el astrocito muere y la mielina se pierde después, por arrastre (inflamación y falta de apoyo al oligodendrocito). Las lesiones de la médula son largas, de tres o más segmentos. Antes se confundía con la esclerosis múltiple, pero algunos tratamientos de la EM no le sirven o incluso la empeoran.", "fila": ["SNC: nervio óptico y médula", "Astrocito (acuaporina-4)", "Autoinmune", "Brotes graves; daño de mielina secundario"], "img": "img/glia-if/astrocitos-vasos-gfap.jpg", "ctx": "Astrocitos reales (verde, marcados con GFAP) junto a vasos sanguíneos (los tubos magenta). Fíjate cómo sus prolongaciones llegan a los vasos y los forran por fuera: son los pies perivasculares. En su membrana está la acuaporina-4, el blanco de los anticuerpos en la neuromielitis óptica.", "pie": "GFAP (verde) · vasos sanguíneos (magenta). Jeffery J. Iliff, dominio público, Wikimedia Commons", "img_t": "Ver la célula real"}, {"clave": "cmt", "titulo": "Tomás, 24 años", "corto": "Charcot-Marie-Tooth", "situacion": "Desde niño se tropieza y se le tuercen los tobillos. Tiene el arco del pie muy alto, los dedos en garra y las piernas delgadas bajo la rodilla; ahora también le cuesta abrochar botones. Su papá camina igual. Sus nervios conducen lento en brazos y piernas, y empeora muy despacio con los años.", "contexto": "Neuropatía hereditaria: se hereda de uno de los padres. En el tipo 1A hay una copia extra del gen de PMP22, una proteína de la mielina que fabrica la célula que envuelve un solo tramo de un solo axón. Con PMP22 de más, esa mielina se forma mal desde la infancia. No hay ataque del sistema inmune. Se afectan primero los nervios más largos: los de pies y manos.", "foto": "img/glia-accion/casos/cmt.jpg", "foto_t": "Pie de una persona con Charcot-Marie-Tooth tipo 1A: arco muy alto, dedos en garra y poco músculo, porque los nervios largos llevan mal la señal a los músculos del pie y la pierna.", "foto_pie": "Benefros · CC BY-SA 3.0 · Wikimedia Commons", "pasos": [{"tipo": "sistema", "p": "¿Dónde está el daño: en el SNC o en el SNP?", "ops": ["SNC", "SNP"], "ok": 1, "pista": "Pies y manos, con nervios que conducen lento: los nervios más largos del cuerpo."}, {"tipo": "tarjeta", "p": "¿Qué célula fabrica la mielina alterada?", "ops": ["Oligodendrocito", "Célula de Schwann", "Astrocito", "Microglía"], "ok": 1, "pista": "La que envuelve un tramo de un solo axón, en el SNP."}, {"tipo": "elegir", "p": "¿Por qué aquí no sirven los tratamientos que frenan al sistema inmune?", "ops": ["No hay ataque inmune: por un gen alterado, la célula de Schwann forma mal su mielina", "La mielina de los nervios de brazos y piernas no se puede dañar en ningún caso", "Los nervios de pies y manos no reciben células del sistema inmune por la sangre", "El daño está en los músculos de las piernas y no en los nervios que los controlan"], "ok": 0, "pista": "Mira la familia: el papá tiene lo mismo."}], "exp": "Charcot-Marie-Tooth tipo 1A: la neuropatía hereditaria más frecuente. Una copia extra del gen PMP22 (proteína de la mielina periférica) hace que la célula de Schwann forme mielina defectuosa: conducción lenta desde la infancia, que avanza muy despacio. Los músculos de pies y piernas se adelgazan porque reciben poca señal (de ahí el arco alto y los dedos en garra). No hay ataque inmune; el tratamiento es rehabilitación: órtesis, fuerza y prevención de caídas.", "fila": ["SNP: nervios largos (pies y manos)", "Célula de Schwann (PMP22)", "Genética (hereditaria)", "Lenta, de por vida"]}, {"clave": "compara", "titulo": "Compara los cuatro", "corto": "Compara", "vista": "cuadro", "situacion": "Mira tu cuadro comparativo a la izquierda.", "pasos": [{"tipo": "elegir", "p": "¿En cuál de los cuatro pacientes esperas que la mielina se recupere mejor?", "ops": ["Jorge (Guillain-Barré): la célula de Schwann remieliniza y guía al axón", "Valentina (esclerosis múltiple): el oligodendrocito se divide y repone toda la mielina", "Matías (neuromielitis óptica): el astrocito se transforma en oligodendrocito", "Tomás (Charcot-Marie-Tooth): la mielina se corrige sola con los años"], "ok": 0, "pista": "¿Qué sistema repara mejor: el SNP o el SNC? ¿Y qué pasa si el defecto está en el gen?"}], "exp": "El SNP repara mejor: la célula de Schwann limpia, remieliniza y guía al axón. En el SNC la remielinización depende de los precursores NG2 y queda incompleta. Y si el defecto está en el gen de una proteína de la mielina, la célula sigue fabricándola mal."}]}, {"n": 4, "tipo": "escenas", "modo": "etapas", "dx": true, "titulo": "Tras la lesión: SNP frente a SNC", "subtitulo": "La secuencia por etapas y 10 hechos para clasificar", "fondo": "img/glia-accion/lesion-comparacion.jpg", "vb": [1200, 984], "alt": "Qué pasa tras cortar un axón en un nervio (arriba) y en la médula (abajo), en cuatro etapas", "cols": [[0, 302], [302, 601], [601, 903], [903, 1200]], "filas_y": [[38, 418], [460, 984]], "cols_t": ["Etapa 1 · antes", "Etapa 2 · tras el corte", "Etapa 3 · días a semanas", "Etapa 4 · resultado"], "ampliar_t": "Arriba, un axón de un nervio que llega al músculo (SNP); abajo, un axón de la médula con su oligodendrocito (SNC). 1: antes de la lesión. 2: justo después del corte. 3: días a semanas. 4: el resultado.", "cuadro_etapas": {"filas": ["2 · Tras el corte", "3 · Días a semanas", "4 · Resultado"], "cols": ["Solo SNP", "Solo SNC", "En ambos"]}, "guia_img": "Tras cortar un axón: SNP (arriba) y SNC (abajo)", "guia_pie": "Las cuatro etapas con sus rótulos.", "instrucciones": "Primero <strong>mira la secuencia</strong>: qué pasa tras cortar un axón en un <strong>nervio</strong> (SNP, arriba) y en la <strong>médula</strong> (SNC, abajo). Cada etapa se destapa y se anima en la imagen; lo que pasa en cada fila está en el panel. Después <strong>clasifica 10 hechos</strong>: ¿ocurren solo en el SNP, solo en el SNC o en ambos? La etapa de cada hecho se marca en la imagen y cada acierto se anota en el cuadro por etapa. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.", "casos": [{"clave": "e1", "titulo": "1 · Antes de la lesión", "corto": "1 · Antes", "col": 0, "pasos": [{"tipo": "mira", "boton": "Siguiente etapa →"}], "snp": "Un axón motor llega al músculo. Cada célula de Schwann envuelve un tramo de ese único axón.", "snc": "Un axón de la médula. Su mielina la forma un oligodendrocito, que envuelve tramos de varios axones.", "anim": {"rotulos": [{"x": 62, "y": 238, "t": "Célula de Schwann", "s": 1.0}, {"x": 250, "y": 150, "t": "Músculo", "i": 1, "s": 1.6}, {"x": 120, "y": 800, "t": "Oligodendrocito", "s": 2.4}]}}, {"clave": "e2", "titulo": "2 · Justo después del corte", "corto": "2 · Corte", "col": 1, "pasos": [{"tipo": "mira", "boton": "Siguiente etapa →"}], "snp": "El tramo que quedó separado de su soma se desarma junto con su mielina: degeneración walleriana.", "snc": "Pasa lo mismo: el tramo separado se fragmenta. El extremo que sigue unido al soma sobrevive.", "anim": {"efectos": [{"l": [[[418, 196], [418, 286]]], "w": 6, "c": "#EF4444", "t": 0.9, "a": "pulso"}, {"l": [[[454, 684], [454, 762]]], "w": 6, "c": "#EF4444", "t": 2.2, "a": "pulso"}], "rotulos": [{"x": 418, "y": 196, "t": "Corte", "i": 1, "s": 1.0}, {"x": 545, "y": 300, "t": "Se fragmenta", "s": 1.6, "i": 1}, {"x": 454, "y": 684, "t": "Corte", "i": 1, "s": 2.3}, {"x": 548, "y": 836, "t": "Se fragmenta", "i": 1, "s": 2.9}]}}, {"clave": "e3", "titulo": "3 · Días a semanas", "corto": "3 · Días", "col": 2, "pasos": [{"tipo": "mira", "boton": "Siguiente etapa →"}], "snp": "Llegan macrófagos y, junto con las células de Schwann, limpian los restos en pocos días. Las Schwann se alinean y forman un tubo por el que el axón empieza a crecer.", "snc": "La microglía limpia lento: los restos de mielina quedan semanas o meses. Los astrocitos se vuelven reactivos: crecen y se multiplican.", "anim": {"flujos": [{"d": "M700 240 L842 240", "f": "cono", "n": 1, "dur": 3, "t": 2.0}], "rotulos": [{"x": 690, "y": 140, "t": "Macrófago", "s": 1.0}, {"x": 842, "y": 268, "t": "Tubo de Schwann", "s": 1.8, "i": 1}, {"x": 720, "y": 680, "t": "Microglía", "s": 2.6}, {"x": 845, "y": 872, "t": "Astrocito reactivo", "i": 1, "s": 3.2}]}}, {"clave": "e4", "titulo": "4 · Semanas a meses: el resultado", "corto": "4 · Resultado", "col": 3, "pasos": [{"tipo": "mira", "boton": "Ahora, a clasificar →"}], "snp": "El axón crece cerca de 1 mm al día por el tubo, vuelve a inervar el músculo y se remieliniza, con internodos más cortos.", "snc": "Los astrocitos forman una cicatriz glial densa. El axón llega hasta ella, se hincha en un bulbo y se detiene.", "anim": {"flujos": [{"d": "M985 722 L1032 722", "f": "cono", "n": 1, "dur": 1.4, "t": 2.6}], "rotulos": [{"x": 1150, "y": 245, "t": "Vuelve al músculo", "i": 1, "s": 1.0}, {"x": 1065, "y": 575, "t": "Cicatriz glial", "i": 1, "s": 1.9}, {"x": 1012, "y": 748, "t": "Bulbo: se detiene", "s": 2.6}]}}, {"clave": "clasifica", "titulo": "Clasifica 10 hechos", "corto": "Clasifica", "situacion": "Ya viste la secuencia. Lee cada hecho y decide si ocurre solo en el SNP, solo en el SNC o en ambos. Su etapa queda marcada en la imagen; con «Ver cuadro» ves lo que llevas.", "pasos": [{"tipo": "sistema", "p": "El tramo del axón que quedó separado de su soma se desarma junto con su mielina (degeneración walleriana).", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 2, "pista": "Mira la etapa 2 en las dos filas.", "exp": "Sin contacto con su soma, el tramo distal del axón se fragmenta en pocos días, tanto en un nervio como en la médula.", "col": 1, "fila": "2 · Tras el corte", "celda": "Degeneración walleriana"}, {"tipo": "sistema", "p": "La neurona sobrevive al corte e intenta hacer crecer su axón otra vez.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 2, "pista": "¿Cuál es el problema en la médula: la neurona o lo que la rodea?", "exp": "En los dos sistemas la neurona intenta crecer; lo que cambia es el ambiente. Con un injerto de nervio periférico (con células de Schwann), axones del SNC crecen centímetros (experimento de Aguayo).", "col": 1, "fila": "2 · Tras el corte", "celda": "La neurona intenta crecer"}, {"tipo": "sistema", "p": "Macrófagos y células de Schwann limpian los restos de mielina en pocos días.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 0, "pista": "Las células de Schwann solo están en los nervios.", "exp": "En el SNP la limpieza es rápida: así el camino queda libre para el axón que vuelve a crecer.", "col": 2, "fila": "3 · Días a semanas", "celda": "Limpieza rápida (días)"}, {"tipo": "sistema", "p": "Los restos de mielina quedan semanas o meses y frenan al axón, porque tienen proteínas que inhiben su crecimiento (Nogo y MAG).", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 1, "pista": "¿Qué mielina tiene esas proteínas: la del oligodendrocito o la de Schwann?", "exp": "La mielina del oligodendrocito trae proteínas inhibidoras y se limpia lento: el axón choca con ellas.", "col": 2, "fila": "3 · Días a semanas", "celda": "Restos de mielina que frenan (meses)"}, {"tipo": "sistema", "p": "La microglía se activa y los astrocitos se vuelven reactivos: más grandes y con más GFAP (su filamento intermedio).", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 1, "pista": "Microglía y astrocitos son glía del SNC.", "exp": "Es la glía reactiva de la etapa 3 en la fila de abajo: defiende y limpia, pero también inflama.", "col": 2, "fila": "3 · Días a semanas", "celda": "Microglía y astrocitos reactivos"}, {"tipo": "sistema", "p": "Las células de Schwann se alinean dentro de su lámina basal y forman un tubo que guía al axón (bandas de Büngner).", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 0, "pista": "Busca el tubo de células alineadas en la etapa 3.", "exp": "El tubo guía es la gran ventaja del SNP: el axón crece por dentro, sin perderse.", "col": 2, "fila": "3 · Días a semanas", "celda": "Tubo guía de Schwann"}, {"tipo": "sistema", "p": "El axón crece cerca de 1 mm al día por dentro del tubo, hasta llegar al músculo.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 0, "pista": "¿En qué fila el axón llega de nuevo a su destino?", "exp": "Por eso la recuperación de un nervio toma semanas a meses: depende de la distancia hasta el músculo.", "col": 3, "fila": "4 · Resultado", "celda": "Rebrote ~1 mm/día"}, {"tipo": "sistema", "p": "El axón vuelve a inervar el músculo y se remieliniza, con internodos más cortos que antes.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 0, "pista": "Mira la etapa 4 de la fila de arriba.", "exp": "La función vuelve, aunque la conducción puede quedar algo más lenta y la reinervación no siempre es exacta.", "col": 3, "fila": "4 · Resultado", "celda": "Reinervación del músculo"}, {"tipo": "sistema", "p": "Una barrera densa de astrocitos (cicatriz glial) aísla la lesión y el axón queda detenido frente a ella.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 1, "pista": "Mira la etapa 4 de la fila de abajo.", "exp": "La cicatriz protege el tejido sano y vuelve a sellar la barrera, pero frena al axón: en el SNC la recuperación depende de la plasticidad.", "col": 3, "fila": "4 · Resultado", "celda": "Cicatriz glial; axón detenido"}, {"tipo": "sistema", "p": "Un nervio aplastado (con su vaina intacta) se recupera mejor que uno cortado, porque cada axón vuelve a crecer por su propio tubo.", "ops": ["Solo SNP", "Solo SNC", "En ambos"], "ok": 0, "pista": "Es una lesión de nervio.", "exp": "En el corte hay que reunir los extremos y muchos axones se desordenan al cruzar la brecha; en el aplastamiento cada uno sigue su camino.", "col": 3, "fila": "4 · Resultado", "celda": "Aplastamiento > corte"}], "exp": "En los dos sistemas el tramo separado se degenera y la neurona intenta crecer: lo que cambia es el ambiente. En el SNP, macrófagos y células de Schwann limpian rápido y forman un tubo que guía al axón hasta el músculo. En el SNC la limpieza es lenta, la mielina del oligodendrocito frena con Nogo y MAG, y los astrocitos forman una cicatriz que detiene al axón."}], "recortes": [{"t": "SNP · nervio (llega al músculo)", "c": "snp", "y": [85, 415]}, {"t": "SNC · médula espinal", "c": "snc", "y": [540, 960]}]}, {"n": 5, "tipo": "practica", "titulo": "Glía que cambia"}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (8, 13, 2, '¿Qué cruza la barrera?', 'Lee cada sustancia y toca la tarjeta: ¿<strong>pasa libremente</strong>, <strong>pasa con transportador</strong> o <strong>no pasa</strong> la barrera hematoencefálica? Cada acierto se anota en el cuadro. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1),
  (6, 13, 5, 'Glía que cambia', 'La misma célula cambia según lo que pasa a su alrededor. Lee el caso (o mira la imagen) y toca la tarjeta del <strong>estado</strong> en que está la glía. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (8, 'Oxígeno (O₂) que trae la sangre.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Es un gas pequeño.',
      'Los gases difunden a través de las membranas del endotelio.', 1, 'Ejemplos', 'O₂', NULL, NULL),
  (8, 'Dióxido de carbono (CO₂) que sale del tejido nervioso.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Es un gas pequeño.',
      'Difunde en ambos sentidos, de donde hay más a donde hay menos.', 2, 'Ejemplos', 'CO₂', NULL, NULL),
  (8, 'Alcohol y anestésicos generales: moléculas pequeñas y liposolubles.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Lo que se disuelve en lípidos atraviesa la membrana.',
      'Por eso actúan tan rápido sobre el encéfalo.', 3, 'Ejemplos', 'Alcohol, anestésicos', NULL, NULL),
  (8, 'Glucosa, el combustible principal del encéfalo.', 'Pasa con transportador', 'transportador|con transportador',
      'Es hidrosoluble, pero el encéfalo no puede vivir sin ella.',
      'Cruza por GLUT1, la proteína del endotelio que transporta glucosa.', 4, 'Ejemplos', 'Glucosa', NULL, NULL),
  (8, 'Aminoácidos que la neurona usa para fabricar neurotransmisores.', 'Pasa con transportador', 'transportador|con transportador',
      'Son necesarios pero no liposolubles.',
      'Tienen transportadores específicos en el endotelio.', 5, 'Ejemplos', 'Aminoácidos', NULL, NULL),
  (8, 'L-dopa, el fármaco que se usa en el Parkinson.', 'Pasa con transportador', 'transportador|con transportador',
      'Se parece a un aminoácido.',
      'Usa el transportador de aminoácidos; dentro del encéfalo se transforma en dopamina.', 6, 'Ejemplos', 'L-dopa', NULL, NULL),
  (8, 'Dopamina en pastilla, la molécula que falta en el Parkinson.', 'No pasa', 'no|no pasa|bloqueada',
      'Si pasara, ¿para qué se usaría la L-dopa?',
      'No tiene transportador: por eso se da su precursor, la L-dopa.', 7, 'Ejemplos', 'Dopamina', NULL, NULL),
  (8, 'Albúmina y anticuerpos del plasma.', 'No pasa', 'no|no pasa|bloqueada',
      'Son proteínas grandes.',
      'Las proteínas plasmáticas quedan fuera: el LCR casi no tiene proteínas.', 8, 'Ejemplos', 'Proteínas del plasma', NULL, NULL),
  (8, 'Bacterias que circulan por la sangre.', 'No pasa', 'no|no pasa|bloqueada',
      'Son mucho más grandes que una molécula.',
      'Si la barrera se daña (meningitis), pueden entrar.', 9, 'Ejemplos', 'Bacterias', NULL, NULL),
  (8, 'La mayoría de los fármacos, como muchos antibióticos y quimioterapias.', 'No pasa', 'no|no pasa|bloqueada',
      'Es uno de los grandes desafíos para tratar el encéfalo.',
      'Por eso hay que diseñar fármacos que usen transportadores o se den dentro del LCR.', 10, 'Ejemplos', 'Mayoría de los fármacos', NULL, NULL),
  (8, 'Una toxina de la sangre llega a las neuronas del área postrema (un órgano circunventricular) y provoca vómito.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'En los órganos circunventriculares los capilares sí tienen poros.',
      'Son zonas sin barrera: así el encéfalo «muestrea» la sangre.', 11, 'Ejemplos', 'Órganos circunventriculares', NULL, NULL),
  (6, 'Tejido sano: sus ramas se mueven todo el tiempo y escanean el tejido en pocas horas. Cada célula ocupa su propio territorio.', 'Microglía vigilante', 'vigilante|microglia vigilante|m0|reposo',
      '«En reposo» es un nombre engañoso: nunca está quieta.',
      'Es el estado basal (M0): monitorea el ambiente y detecta señales de peligro.', 1, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-iba1.jpg", "pie": "Iba1 (rojo) · ADN (azul). J. Wegiel, CC BY 4.0, Wikimedia Commons", "mini": true, "ctx": "Esta es la imagen real: corte de cerebro donde un anticuerpo (Iba1) pinta de rojo a la microglía y en azul se ven los núcleos de todas las células. Fíjate en las ramas finas y en que cada célula ocupa su propio espacio, sin tocar a sus vecinas: así se ve la microglía vigilante."}'),
  (6, 'Detecta restos de un patógeno: se redondea, fagocita y libera TNF-α e IL-1β (citoquinas proinflamatorias: mensajeros que encienden la inflamación).', 'Microglía M1 (inflamatoria)', 'm1|proinflamatoria|inflamatoria|microglia m1',
      'Fagocitosis más citoquinas inflamatorias.',
      'M1: defensa y limpieza. Si se cronifica, daña neuronas, sinapsis y mielina.', 2, NULL, NULL, NULL, NULL),
  (6, 'En un ambiente con IL-4 e IL-10 (citoquinas antiinflamatorias) secreta BDNF (un factor que nutre y protege a las neuronas) y ayuda a resolver la inflamación.', 'Microglía M2 (reparadora)', 'm2|reparadora|antiinflamatoria|microglia m2',
      'Factores neurotróficos y resolución.',
      'M2: reparación del tejido, formación de vasos y apoyo a las neuronas.', 3, NULL, NULL, NULL, NULL),
  (6, 'En el Alzheimer, la microglía queda activada por años y contribuye a la poda excesiva de sinapsis y a la excitotoxicidad.', 'Microglía M1 (inflamatoria)', 'm1|proinflamatoria|inflamatoria|microglia m1',
      'Es el lado dañino de la activación.',
      'La neuroinflamación crónica es un motor del deterioro en enfermedades neurodegenerativas.', 4, NULL, NULL, NULL, NULL),
  (6, 'Corteza de un modelo de Alzheimer: los astrocitos (rojo) rodean las placas (verde), aumentan el complemento C3 (una proteína inmune que marca sinapsis para eliminarlas) y dañan sinapsis.', 'Astrocito A1 (tóxico)', 'a1|neurotoxico|toxico|astrocito a1',
      'Los induce la microglía activada con sus señales inflamatorias (IL-1α, TNF y C1q).',
      'A1: pierden sus funciones de apoyo y se vuelven tóxicos para neuronas y oligodendrocitos.', 5, NULL, NULL, NULL, '{"img": "img/glia-if/astrocitos-placas.jpg", "pie": "GFAP (rojo) · placas de amiloide (verde). Pics56, CC BY-SA 4.0, Wikimedia Commons", "mini": true, "ctx": "Esta es la imagen real: corteza de un ratón que modela el Alzheimer. En verde, las placas de amiloide (proteína acumulada); en rojo, astrocitos marcados con GFAP. Mira cómo los astrocitos se agrupan y engrosan alrededor de cada placa: están reactivos."}'),
  (6, 'Tras una isquemia aparecen astrocitos que liberan factores que protegen a las neuronas y reparan sinapsis.', 'Astrocito A2 (protector)', 'a2|protector|neuroprotector|astrocito a2',
      'Los induce la isquemia.',
      'A2: neuroprotectores. Hoy A1 y A2 se entienden como extremos de un continuo.', 6, NULL, NULL, NULL, NULL),
  (6, 'Junto a la lesión, astrocitos más grandes que se multiplican y aumentan GFAP (su filamento intermedio) y CSPG (proteoglicanos: moléculas del espacio entre células que frenan al axón).', 'Astrocito de la cicatriz', 'cicatriz|astrocito de la cicatriz|formador de cicatriz',
      'Es la barrera que viste en el nivel IV, en la médula.',
      'Aísla la lesión y protege el tejido sano, pero los CSPG frenan el crecimiento del axón.', 7, NULL, NULL, NULL, NULL),
  (6, 'En el embrión, sus prolongaciones van del ventrículo a la superficie y sirven de riel a las neuronas que migran.', 'Glía radial', 'radial|glia radial',
      'Es glía del desarrollo.',
      'Es precursora de neuronas y astrocitos; al terminar la migración se transforma en astrocito. Si falla la migración: displasias corticales y epilepsia.', 8, NULL, NULL, NULL, NULL),
  (6, 'Las células verdes (marcadas con NG2, una proteína de su membrana), pequeñas y ramificadas, persisten en el adulto y pueden convertirse en células que vuelven a formar mielina.', 'Precursor NG2', 'ng2|opc|precursor|precursor de oligodendrocito',
      'Mira el color verde y piensa en quién mieliniza el SNC.',
      'Son precursores de oligodendrocitos (OPC). En la esclerosis múltiple migran a la placa y remielinizan, aunque con mielina más delgada.', 9, NULL, NULL, NULL, '{"img": "img/glia-if/ng2-gfap.jpg", "pie": "NG2 (verde) · GFAP (rojo) · núcleos (azul). O. Tsupykov, CC BY-SA 4.0, Wikimedia Commons", "mini": true, "ctx": "Esta es la imagen real: encéfalo adulto con tres marcas. En verde, células NG2 (precursores de oligodendrocito); en rojo, astrocitos (GFAP); en azul, núcleos. Las verdes son pequeñas y ramificadas: siguen en el adulto, listas para formar mielina nueva."}');

-- Actividad 12: QUIZ de cierre Células nerviosas II (la glía)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo) VALUES
  (12, 7, 'quiz-celulas-nerviosas-2', 'Quiz: Células nerviosas II (la glía)',
       'Cierre del práctico: preguntas de un pool común y casos de tu carrera (TO o Fono); algunas se responden con tarjetas. Una sola oportunidad por pregunta; cada respuesta muestra una explicación.', 'quiz', 1);
INSERT OR IGNORE INTO quices (actividad_id, titulo, datos_json, activo) VALUES
  (12, 'Células nerviosas II', '[{"id": "c01", "carrera": "comun", "pregunta": "En el encéfalo humano, ¿cuál es la proporción aproximada entre glía y neuronas?", "opciones": ["Cerca de 1 glía por cada neurona", "10 glías por cada neurona", "1 glía por cada 10 neuronas", "50 glías por cada neurona"], "correcta": 0, "feedback": "Los recuentos actuales dan una proporción cercana a 1:1 en el encéfalo humano; la idea de «10 veces más glía» es un mito."}, {"id": "c02", "carrera": "comun", "pregunta": "¿Qué célula glial no nace del tejido nervioso, sino de precursores inmunes (mesodermo)?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 2, "feedback": "La microglía viene de los mismos precursores que los macrófagos y entra al SNC durante el desarrollo.", "tarjetas": true}, {"id": "c04", "carrera": "comun", "pregunta": "Durante el desarrollo se forman más sinapsis de las necesarias. ¿Qué célula elimina las que no se usan (poda sináptica)?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 2, "feedback": "La microglía poda las sinapsis poco activas; así se refinan los circuitos. Una poda excesiva se asocia a enfermedades del neurodesarrollo y neurodegenerativas.", "tarjetas": true}, {"id": "c05", "carrera": "comun", "pregunta": "Un axón del nervio ciático está mielinizado por muchas células, una detrás de otra. ¿Cuáles son?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "En el SNP cada célula de Schwann forma un solo internodo: un axón largo necesita cientos de ellas en fila.", "tarjetas": true}, {"id": "c08", "carrera": "comun", "pregunta": "La barrera hematoencefálica impide que la mayoría de los fármacos llegue al encéfalo. ¿Qué forma el sello que los detiene?", "opciones": ["Uniones estrechas entre las células del endotelio capilar", "Pies de astrocitos pegados unos a otros, sin espacios", "Una capa de mielina que envuelve a cada capilar cerebral", "Células ependimarias que tapizan los vasos sanguíneos"], "correcta": 0, "feedback": "La barrera es una propiedad del endotelio: sus uniones estrechas sellan el paso entre células. Los pies astrocitarios la inducen y la mantienen, pero no son el sello."}, {"id": "c11", "carrera": "comun", "pregunta": "En el Parkinson falta dopamina, pero se trata con L-dopa y no con dopamina. ¿Por qué?", "opciones": ["La L-dopa cruza la barrera por un transportador y la dopamina no puede cruzarla", "La dopamina es tóxica para el hígado y la L-dopa no", "La L-dopa forma mielina nueva en los axones dopaminérgicos", "La dopamina cruza la barrera, pero la microglía la destruye"], "correcta": 0, "feedback": "La L-dopa usa el transportador de aminoácidos del endotelio; dentro del encéfalo se convierte en dopamina."}, {"id": "c09", "carrera": "comun", "pregunta": "Tras cortarse, un axón del nervio mediano puede volver a crecer, pero uno de la médula espinal casi no. ¿Qué explica la diferencia?", "opciones": ["En el SNP la célula de Schwann forma un tubo guía; en el SNC hay cicatriz glial", "En el SNP el axón es más grueso; en el SNC los axones son demasiado delgados", "En el SNP no hay glía que estorbe; en el SNC los oligodendrocitos se dividen", "En el SNP la neurona se divide; en el SNC las neuronas maduras no se dividen"], "correcta": 0, "feedback": "La célula de Schwann y su lámina basal guían al axón (~1 mm/día). En el SNC, los astrocitos reactivos forman la cicatriz glial y la mielina del oligodendrocito tiene inhibidores del crecimiento."}, {"id": "c12", "carrera": "comun", "pregunta": "Un estímulo doloroso produce primero un dolor agudo y, un segundo después, uno sordo y quemante. ¿Qué explica la demora del segundo?", "opciones": ["Viaja por fibras C, delgadas y sin mielina, que conducen lento", "Viaja por fibras Aα, gruesas y mielinizadas, que conducen lento", "Tiene que pasar primero por el oligodendrocito de la piel", "Espera a que la microglía libere citoquinas en la médula"], "correcta": 0, "feedback": "Dolor agudo: fibras Aδ (finas, con poca mielina). Dolor sordo: fibras C, sin mielina, ~0,5-2 m/s, envueltas por células de Schwann no mielinizantes."}, {"id": "k1", "carrera": "comun", "pregunta": "Una persona con diabetes pierde el reflejo aquíleo y la sensibilidad en los pies; el estudio muestra conducción lenta en los nervios de las piernas. ¿Qué glía está dañada?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "La conducción lenta en nervios periféricos indica daño de la mielina del SNP, que forman las células de Schwann.", "tarjetas": true}, {"id": "k2", "carrera": "comun", "pregunta": "En un brote de esclerosis múltiple, la resonancia muestra placas en la sustancia blanca del encéfalo. ¿Qué célula es el blanco del daño?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 1, "feedback": "La esclerosis múltiple destruye la mielina del SNC, que forman los oligodendrocitos.", "tarjetas": true}, {"id": "k4", "carrera": "comun", "pregunta": "Después de un herpes zóster, una persona queda con dolor quemante sin lesión visible en la piel. ¿Qué glía del ganglio sensitivo se asocia a ese dolor neuropático?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 2, "feedback": "El virus queda latente en el ganglio sensitivo. Las células satélite alteradas dejan a la neurona hiperexcitable: dolor neuropático.", "tarjetas": true}, {"id": "t2", "carrera": "terapia-ocupacional", "pregunta": "En la rehabilitación tras un ACV, la práctica repetida favorece la formación de sinapsis nuevas y la eliminación de las que no se usan. ¿Qué glía participa?", "opciones": ["Astrocitos (forman sinapsis) y microglía (poda las que no se usan)", "Oligodendrocitos (forman sinapsis) y ependimarias (podan las que sobran)", "Células de Schwann (forman sinapsis) y satélite (podan las que sobran)", "Microglía (forma sinapsis) y astrocitos (podan las que no se usan)"], "correcta": 0, "feedback": "Los astrocitos favorecen la sinaptogénesis y la plasticidad; la microglía poda sinapsis. Ambas son parte de la base celular de la rehabilitación."}, {"id": "t3", "carrera": "terapia-ocupacional", "pregunta": "En la ELA, astrocitos que recaptan poco glutamato contribuyen a la muerte de las motoneuronas. ¿Cuál es el mecanismo?", "opciones": ["El glutamato se acumula en la sinapsis y sobreexcita a la neurona", "Falta glutamato en la sinapsis y la neurona deja de recibir señales", "Los astrocitos fagocitan a las motoneuronas que tienen poco glutamato", "El glutamato destruye la mielina que rodea al axón de la motoneurona"], "correcta": 0, "feedback": "Excitotoxicidad: el exceso de glutamato abre demasiados canales, entra Ca2+ en exceso y la neurona muere."}, {"id": "t5", "carrera": "terapia-ocupacional", "pregunta": "Una persona se corta el nervio mediano en la muñeca, a unos 10 cm de los músculos de la mano que inerva. Si el axón crece ~1 mm al día, ¿cuándo esperas los primeros signos de reinervación?", "opciones": ["En unos 3 meses", "En unos 3 días", "En unos 3 años", "Nunca: el SNP no regenera"], "correcta": 0, "feedback": "100 mm ÷ 1 mm/día ≈ 100 días. Mientras tanto se mantiene la movilidad, se protege la piel sin sensibilidad y se reeduca la sensibilidad."}, {"id": "t6", "carrera": "terapia-ocupacional", "pregunta": "Una persona con esclerosis múltiple refiere fatiga y torpeza que empeoran al final del día y con calor. ¿Qué explica estos síntomas?", "opciones": ["Sus axones sin mielina conducen lento o bloquean el impulso", "Sus motoneuronas mueren por falta de glutamato en la sinapsis", "Sus células de Schwann forman cicatriz en los nervios de la mano", "Su microglía forma más mielina de la que los axones necesitan"], "correcta": 0, "feedback": "En el SNC desmielinizado la conducción saltatoria falla: la señal se enlentece o se bloquea. El calor empeora aún más la conducción en esas zonas."}, {"id": "f2", "carrera": "fonoaudiologia", "pregunta": "En la esclerosis múltiple puede aparecer habla lenta y entrecortada (disartria) por placas en el tronco y el cerebelo. ¿Por qué se altera la señal?", "opciones": ["Se pierde la mielina de los oligodendrocitos y la señal se enlentece", "Se pierde la mielina de las células de Schwann: el impulso se acelera", "Mueren las motoneuronas de la lengua: el músculo se atrofia", "Se bloquean las sinapsis por exceso de LCR en los ventrículos"], "correcta": 0, "feedback": "Las placas desmielinizan axones del SNC: la conducción se enlentece o se bloquea y se pierde la coordinación fina de la articulación."}, {"id": "f3", "carrera": "fonoaudiologia", "pregunta": "Un schwannoma vestibular (neurinoma del acústico) produce hipoacusia de un lado y tinnitus. ¿De qué células nace este tumor?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "Nace de las células de Schwann del nervio vestibular; al crecer comprime el nervio coclear vecino.", "tarjetas": true}, {"id": "f4", "carrera": "fonoaudiologia", "pregunta": "Cerca del tronco encefálico, la mielina del nervio auditivo deja de formarla la célula de Schwann y pasa a formarla el oligodendrocito. ¿Qué indica ese cambio?", "opciones": ["Que el nervio pasa del SNP al SNC", "Que el nervio pasa de sensitivo a motor", "Que el axón termina y empieza otro", "Que el nervio pierde toda su mielina"], "correcta": 0, "feedback": "La zona de transición marca el límite SNP–SNC. Los schwannomas vestibulares suelen nacer cerca de esa zona."}, {"id": "f5", "carrera": "fonoaudiologia", "pregunta": "Tras una cirugía de tiroides, una persona queda con voz débil por lesión del nervio laríngeo recurrente. ¿Por qué es posible que la voz se recupere?", "opciones": ["Es un nervio del SNP: la célula de Schwann guía el rebrote del axón", "Es un nervio del SNC: el oligodendrocito forma mielina nueva en él", "La laringe forma neuronas nuevas que reemplazan a las que se dañaron", "La microglía del nervio forma una cicatriz que vuelve a conducir"], "correcta": 0, "feedback": "El laríngeo recurrente es una rama del vago (SNP): su axón puede volver a crecer guiado por las células de Schwann. La terapia mantiene la musculatura y acompaña la recuperación."}]', 1);

INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (12, 2, 'Responde solo/a, sin apuntes. Al terminar revisa el resumen: las preguntas falladas son las que conviene repasar.', 1);

-- Actividad 15: EL POTENCIAL DE ACCIÓN (práctico 3) · simulador propio js/sim-pa.js (Hodgkin y Huxley; reposo −70, umbral ≈ −55, peak ≈ +35, mínimo ≈ −81 mV)
-- + esquemas SVG (img/potencial/, docs/practico-3_svg2.py). I local frente a acción (umbral, todo o nada, sumación temporal; decremento y sumación espacial en esquema);
-- II fases y canales (cursor sobre el registro; cuadro de la guía 2025); III período refractario (absoluto, relativo; un solo sentido en el axón)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (15, 2, 'potencial-accion-neurona', 'El potencial de acción',
       'De los potenciales locales al potencial de acción, con el simulador de NeuroLab. Nivel I: umbral, todo o nada y sumación temporal. Nivel II: las fases y el estado de los canales en cada una. Nivel III: el período refractario.',
       'lamina', 1, 'Diferenciar potencial local y potencial de acción, identificar las fases del potencial de acción y explicarlas por el estado de los canales de Na⁺ y K⁺, y reconocer los períodos refractarios.',
       'Estimular en el simulador con distinta intensidad y frecuencia; recorrer el registro con el cursor para ver los canales en cada fase; completar el cuadro de canales por fase; tocar en el axón.',
       'Guía de laboratorio Neurotransmisión ETMP097 2025 · modelo de Hodgkin y Huxley (1952) · simulador y esquemas de NeuroLab');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (15, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "escenas", "modo": "casos", "simulador": "pa", "titulo": "Del potencial local al potencial de acción", "subtitulo": "Umbral, todo o nada y sumación", "fondo": "img/potencial/guia-pa-1.svg", "vb": [1200, 750], "alt": "Potenciales locales y potencial de acción", "cuadro": ["Estímulo", "¿Llega al umbral?", "Resultado"], "guia_src": "img/potencial/guia-pa-1.svg", "guia_img": "Potencial local y potencial de acción", "guia_pie": "Los potenciales locales crecen con el estímulo y se suman; el potencial de acción es todo o nada. Curvas del simulador.", "instrucciones": "En cada caso haz lo que pide la lista en el <strong>simulador</strong>: se marca sola cuando termina el registro y, al completarla, se habilita la pregunta. Elige la intensidad (1 débil … 5 fuerte) y presiona <strong>⚡ Estimular</strong>: el electrodo inyecta corriente en el soma y el otro registra el potencial en el cono axónico. Cada registro dura 20 ms (el simulador va 400 veces más lento) y el anterior queda en gris para comparar. En un registro caben dos estímulos, el segundo justo después del primero.", "casos": [{"clave": "debil", "titulo": "Un estímulo débil", "corto": "Débil", "situacion": "La neurona está en reposo (−70 mV).", "pasos": [{"tipo": "sim", "p": "Estimula con intensidad 1 o 2:", "checks": [{"t": "Intensidad 1 o 2", "c": "nivelBajo"}, {"t": "Registro sin potencial de acción", "c": "sub"}], "pista": "Presiona ⚡ Estimular y espera que termine el registro.", "q": {"p": "¿Qué ocurrió?", "ops": ["Potencial local: no llegó al umbral", "Potencial local: superó el umbral", "Potencial de acción: no llegó al umbral", "Potencial de acción: superó el umbral"], "ok": 0, "pista": "Mira si el cono axónico se encendió y compara la curva con la línea roja."}}], "fila": ["No", "Potencial local que se apaga"], "exp": "Un estímulo débil produce un potencial local: pequeño, graduado (crece con el estímulo) y que se apaga en pocos milisegundos. Si no alcanza el umbral (≈ −55 mV), no hay potencial de acción."}, {"clave": "fuerte", "titulo": "Estímulos más fuertes", "corto": "Más fuerte", "pasos": [{"tipo": "sim", "p": "Dispara un potencial de acción con intensidad 3 y luego otro más intenso:", "checks": [{"t": "Potencial de acción con intensidad 3", "c": "pa3"}, {"t": "Otro con intensidad 4 o 5", "c": "pa45"}], "pista": "Un estímulo por registro; espera que termine antes del siguiente.", "q": {"p": "Al subir la intensidad, el potencial de acción…", "ops": ["Mantuvo su altura", "Aumentó su altura", "Disminuyó su altura", "Duró el doble"], "ok": 0, "pista": "Compara el peak de la curva morada con el de la gris."}}], "fila": ["Sí", "Potencial de acción de igual altura"], "exp": "El potencial de acción es «todo o nada»: si se alcanza el umbral, su forma y su altura (peak ≈ +35 mV) no dependen del estímulo. La intensidad de un estímulo se codifica en la frecuencia de potenciales de acción y en cuántas neuronas disparan. «Todo o nada» vale para un potencial de acción que parte del reposo: justo después, la membrana es refractaria (nivel III)."}, {"clave": "suma", "titulo": "Dos estímulos débiles seguidos", "corto": "Sumación", "pasos": [{"tipo": "sim", "p": "Con intensidad 2, estimula dos veces seguidas:", "checks": [{"t": "Intensidad 2", "c": "nivel2"}, {"t": "Potencial de acción con dos estímulos de intensidad 2", "c": "suma"}], "pista": "Presiona ⚡ Estimular dos veces rápido; después el botón queda gris hasta que termine el registro.", "q": {"p": "¿Por qué apareció el potencial de acción?", "ops": ["Se sumaron y llegaron al umbral", "Se restaron y bajaron del umbral", "El segundo fue más intenso", "El primero abrió los canales de K⁺"], "ok": 0, "pista": "Uno solo de intensidad 2 no lo lograba."}}], "fila": ["Sí, sumados", "Potencial de acción por sumación temporal"], "exp": "Sumación temporal: un segundo potencial local llega antes de que el primero se apague y la suma alcanza el umbral. Ahí se abren en cadena los canales de Na⁺ controlados por voltaje."}], "sim_cfg": {"vista": "neurona", "max": 2, "ventana": 2, "fondo": "img/potencial/neurona-simple.jpg"}, "dx": true, "nombres_paso": {"elegir": "Pregunta"}}, {"n": 2, "tipo": "escenas", "modo": "casos", "simulador": "pa", "titulo": "Las fases y sus canales", "subtitulo": "Despolarización, repolarización e hiperpolarización", "fondo": "img/potencial/guia-pa-2.svg", "vb": [1200, 750], "alt": "Potencial de acción con sus tres fases", "cuadro": ["Fase", "Canales de Na⁺", "Canales de K⁺", "Ion que se mueve"], "guia_src": "img/potencial/guia-pa-2.svg", "guia_img": "Las fases del potencial de acción", "guia_pie": "a despolarización (entra Na⁺) · b repolarización (Na⁺ inactivado, sale K⁺) · c hiperpolarización (el K⁺ cierra lento). Valores del simulador.", "instrucciones": "Presiona <strong>⚡ Estimular</strong> para disparar un potencial de acción y, cuando termine el registro, <strong>arrastra el cursor</strong> sobre la curva: el voltímetro y los canales de la membrana muestran ese instante, con una flecha en cada canal por donde pasa un ion. En cada caso lleva el cursor a la fase que se pide y responde. Los canales de Na⁺ tienen dos compuertas: la de activación (afuera) y la de inactivación (la bola roja, adentro); los de K⁺, una sola. Cada fase llena una fila del <strong>cuadro</strong>.", "casos": [{"clave": "despol", "titulo": "a · Despolarización", "corto": "a · Despolarización", "pasos": [{"tipo": "sim", "p": "Dispara un potencial de acción y lleva el cursor a la subida:", "checks": [{"t": "Potencial de acción en el registro", "c": "pa"}, {"t": "Cursor en la subida", "c": "curDespol"}], "pista": "Presiona ⚡ Estimular; cuando termine el registro, arrastra sobre la curva del registro hasta la subida.", "q": {"p": "¿Por qué la subida es tan rápida?", "ops": ["El Na⁺ que entra abre más canales de Na⁺", "El K⁺ que sale abre más canales de Na⁺", "El Na⁺ que entra cierra los canales de K⁺", "El Cl⁻ que entra abre más canales de Na⁺"], "ok": 0, "pista": "Mira cuántos canales de Na⁺ están abiertos al comienzo y al final de la subida."}}], "fila": ["Abiertos", "Cerrados (se abren tarde)", "Na⁺ entra"], "exp": "Al llegar al umbral se abre la compuerta de activación de los canales de Na⁺: entra Na⁺, el interior se despolariza más y eso abre más canales (retroalimentación positiva). Por eso la subida es casi vertical y llega a ≈ +35 mV. Los canales de K⁺ también responden al voltaje, pero más lento."}, {"clave": "repol", "titulo": "b · Repolarización", "corto": "b · Repolarización", "pasos": [{"tipo": "sim", "p": "Lleva el cursor a la bajada, desde el peak:", "checks": [{"t": "Cursor en la bajada", "c": "curRepol"}], "pista": "Arrastra sobre la curva del registro hasta el tramo que baja desde el punto más alto.", "q": {"p": "¿Qué detiene la entrada de Na⁺ en el peak?", "ops": ["Se cierra su compuerta de inactivación", "Se cierra su compuerta de activación", "Se acaba el Na⁺ del medio extracelular", "La bomba saca el Na⁺ que entró"], "ok": 0, "pista": "Mira la bola roja de los canales de Na⁺."}}], "fila": ["Inactivados", "Abiertos", "K⁺ sale"], "exp": "Poco después de abrirse, la compuerta de inactivación tapa los canales de Na⁺ y deja de entrar Na⁺, aunque la membrana siga despolarizada. Mientras, se abren los canales de K⁺: sale K⁺ y el interior vuelve a ser negativo. La bomba Na⁺/K⁺ no participa: es demasiado lenta."}, {"clave": "hiper", "titulo": "c · Hiperpolarización", "corto": "c · Hiperpolarización", "pasos": [{"tipo": "sim", "p": "Lleva el cursor al tramo bajo el reposo:", "checks": [{"t": "Cursor en la hiperpolarización", "c": "curHiper"}], "pista": "Arrastra sobre la curva del registro hasta el tramo que queda bajo la línea del reposo.", "q": {"p": "¿Por qué baja de −70 mV?", "ops": ["El K⁺ sigue saliendo: su canal cierra lento", "El Na⁺ sigue entrando: su canal cierra lento", "La bomba Na⁺/K⁺ se acelera al final", "Entra Cl⁻ por canales que abren al final"], "ok": 0, "pista": "Mira qué canales tienen flecha en este tramo."}}], "fila": ["Cerrados (se recuperan)", "Abiertos (cierran lento)", "K⁺ sigue saliendo"], "exp": "Los canales de K⁺ se cierran lentamente: sale más K⁺ que en reposo y el interior baja a ≈ −81 mV, cerca del potencial de equilibrio del K⁺. Mientras, los canales de Na⁺ se recuperan de la inactivación y quedan cerrados, listos para abrirse otra vez. El simulador usa el modelo de Hodgkin y Huxley (axón de calamar); en una neurona de mamífero el potencial de acción dura ≈ 1–2 ms."}], "sim_cfg": {"max": 1, "intensidad": 3}, "dx": true, "nombres_paso": {"elegir": "Pregunta"}}, {"n": 3, "tipo": "escenas", "modo": "casos", "simulador": "pa", "titulo": "El período refractario", "subtitulo": "Absoluto, relativo y para qué sirve", "fondo": "img/potencial/axon-refractario.jpg", "vb": [1200, 800], "alt": "Neurona con axón mielinizado: segmento inicial y cuatro nodos de Ranvier; el potencial de acción está en el nodo 2", "donde": "el axón", "zonas": {"n1": {"e": [330, 380, 46, 46], "nombre": "el segmento inicial"}, "n2": {"e": [500, 380, 46, 46], "nombre": "el nodo 1"}, "n3": {"e": [670, 380, 46, 46], "nombre": "el nodo 2"}, "n4": {"e": [840, 380, 46, 46], "nombre": "el nodo 3"}, "n5": {"e": [1010, 380, 46, 46], "nombre": "el nodo 4"}}, "guia_src": "img/potencial/guia-pa-3.svg", "guia_img": "Períodos refractarios", "guia_pie": "Rojo: absoluto (ningún estímulo dispara). Amarillo: relativo (solo uno más intenso, y el potencial de acción sale más bajo). Curva del simulador.", "instrucciones": "Ahora cada <strong>⚡ Estimular</strong> da un par de estímulos: el 1.º de intensidad 3 y el 2.º con el <strong>intervalo</strong> y la <strong>intensidad</strong> que elijas. La lista se marca sola cuando termina el registro; con el cursor sobre la curva ves los canales en ese instante. En el último caso, toca en el axón.", "casos": [{"clave": "abs", "titulo": "Durante el potencial de acción", "corto": "Absoluto", "pasos": [{"tipo": "sim", "p": "Prueba un 2.º estímulo muy cercano y míralo con el cursor:", "checks": [{"t": "2.º a los 3 ms con intensidad 5: no dispara", "c": "refAbs"}, {"t": "Cursor sobre la marca ▼ del 2.º estímulo", "c": "cur2do"}], "pista": "Arriba elige 3 ms y, en «Intensidad del 2.º», 5. Presiona ⚡ Estimular (da los dos estímulos) y arrastra el cursor hasta la marca ▼ del 2.º.", "q": {"p": "¿Por qué no hubo un segundo potencial de acción?", "ops": ["Los canales de Na⁺ están inactivados", "Los canales de K⁺ están inactivados", "Se acabó el Na⁺ del medio extracelular", "La bomba Na⁺/K⁺ está apagada"], "ok": 0, "pista": "Mira la bola roja de los canales de Na⁺."}}], "exp": "Período refractario absoluto: mientras los canales de Na⁺ están abiertos o inactivados, ningún estímulo, por intenso que sea, dispara otro potencial de acción. Dura hasta que se recuperan suficientes canales de la inactivación (en el simulador ≈ 6 ms; en una neurona de mamífero ≈ 1 ms)."}, {"clave": "rel", "titulo": "Durante la hiperpolarización", "corto": "Relativo", "pasos": [{"tipo": "sim", "p": "A los 9 ms, prueba el 2.º estímulo con dos intensidades:", "checks": [{"t": "2.º a los 9 ms con intensidad 3: no dispara", "c": "relDebil"}, {"t": "2.º a los 9 ms con intensidad 5: dispara un PA más bajo", "c": "refRel"}], "pista": "Elige 9 ms. En «Intensidad del 2.º» prueba primero 3 y estimula; luego 5 y estimula otra vez. El 1.º siempre es de intensidad 3.", "q": {"p": "¿Por qué con intensidad 3 no hubo 2.º potencial de acción a los 9 ms?", "ops": ["Aún hay canales de Na⁺ inactivados", "Aún hay canales de K⁺ inactivados", "Ya no queda Na⁺ en el medio extracelular", "La bomba Na⁺/K⁺ aún está apagada"], "ok": 0, "pista": "Mira las bolas rojas con el cursor en el 2.º estímulo."}}], "exp": "Período refractario relativo: algunos canales de Na⁺ ya se recuperaron, pero otros siguen inactivados y los de K⁺ siguen abiertos. Solo un estímulo más intenso que lo normal dispara, y el potencial de acción sale más bajo. Con más tiempo (12–15 ms) basta la intensidad normal. Sigue siendo todo o nada: un estímulo aún más fuerte no lo agranda, porque su altura depende de cuántos canales de Na⁺ están disponibles."}, {"clave": "sentido", "titulo": "En el axón", "corto": "Un solo sentido", "esquema": true, "situacion": "El potencial de acción viene desde el soma y ahora está en el nodo 2.", "pasos": [{"tipo": "tocar", "p": "¿A qué nodo vecino no puede pasar ahora? Tócalo.", "ok": ["n2"], "pista": "Piensa por qué nodo pasó hace un instante.", "q": {"p": "¿Por qué no puede pasar a ese nodo?", "ops": ["Sus canales de Na⁺ siguen inactivados", "Sus canales de K⁺ siguen inactivados", "Ya no le queda Na⁺ en el exterior", "La mielina lo aísla del resto"], "ok": 0, "pista": "Ese nodo acaba de disparar: recuerda el período refractario absoluto."}}], "anim": {"efectos": [{"e": [500, 380, 40, 40], "c": "rgba(248,113,113,.45)", "s": "#DC2626", "a": "crece", "t": 0}, {"e": [840, 380, 36, 36], "c": "rgba(245,158,11,.4)", "s": "#F59E0B", "a": "pulso", "t": 0.8}, {"e": [670, 380, 40, 40], "c": "rgba(248,113,113,.45)", "s": "#DC2626", "a": "crece", "t": 1.4}, {"e": [1010, 380, 36, 36], "c": "rgba(245,158,11,.4)", "s": "#F59E0B", "a": "pulso", "t": 2.0}, {"e": [840, 380, 40, 40], "c": "rgba(248,113,113,.45)", "s": "#DC2626", "a": "crece", "t": 2.6}], "rotulos": [{"x": 500, "y": 500, "t": "Refractario", "s": 0.3}, {"x": 1050, "y": 300, "t": "Avanza →", "s": 2.0, "i": 1}]}, "exp": "El nodo que acaba de disparar tiene sus canales de Na⁺ inactivados (período refractario absoluto): la corriente local no puede volver a excitarlo. Por eso el impulso avanza en un solo sentido, del soma hacia los botones terminales. El período refractario también pone un techo a la frecuencia de disparo (cientos de potenciales de acción por segundo)."}], "sim_cfg": {"par": true}, "dx": true, "nombres_paso": {"elegir": "Pregunta"}}]}', NULL, 1);
INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (15, 1, 'En Fonoaudiología: la intensidad de un sonido se codifica en la frecuencia de potenciales de acción del nervio auditivo, y el período refractario pone un límite a esa frecuencia.', 1),
  (15, 2, 'En Terapia Ocupacional: la fuerza de una contracción depende de la frecuencia de potenciales de acción de las motoneuronas y de cuántas se activan.', 2);

-- Actividad 17: CASOS CLÍNICOS DE SINAPSIS (práctico 4, cierre) · «escenas» modo «casos», como el nivel III de la actividad 13
-- Un nivel con 5 casos (isrs, acv, parkinson, miastenia, botox): sitio (tarjeta) → qué cambia → qué se observa; cada caso suma una fila al cuadro
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (17, 10, 'casos-sinapsis', 'Casos clínicos: la sinapsis en la clínica',
       'Cierre del práctico 4: pacientes cuya enfermedad o tratamiento actúa en la sinapsis. En cada caso decides dónde actúa, qué cambia con el neurotransmisor o el receptor y qué se observa en el paciente, y armas un cuadro comparativo.',
       'lamina', 1, 'Relacionar enfermedades y fármacos con el sitio de la sinapsis donde actúan (botón presináptico, hendidura, receptor postsináptico o astrocito) y con el cambio que producen en la neurotransmisión.',
       'Resolver casos clínicos en tres pasos (sitio, qué cambia, qué se observa) con pistas; cada caso suma una fila al cuadro comparativo que va a la guía.',
       'Apuntes del curso ETMP097 · Purves, Neurociencia · Kandel, Principios de neurociencia');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (17, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "escenas", "modo": "casos", "titulo": "La sinapsis en la clínica", "subtitulo": "Cinco casos y su cuadro comparativo", "fondo": "img/glia-accion/neurovascular.jpg", "vb": [1536, 1024], "alt": "Capilar, astrocito y sinapsis", "instrucciones": "Cinco pacientes con un problema o un tratamiento que actúa en la sinapsis. En cada uno, lee el caso y lo que se sabe de la enfermedad o del fármaco, y mira la imagen (tócala para ampliarla). Luego responde: ¿<strong>dónde</strong> actúa?, ¿qué <strong>cambia</strong> con el neurotransmisor o el receptor? y ¿qué se <strong>observa</strong> en el paciente? Cada caso suma una fila a tu cuadro comparativo. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "cuadro": ["Caso", "Sitio", "Neurotransmisor", "Qué cambia", "Efecto"], "guia_img": "Los casos", "guia_pie": "Imágenes: Lanfear''s Bane (CC BY-SA 3.0); Lucien Monfils (CC BY-SA 4.0).", "casos": [{"clave": "isrs", "titulo": "Camila, 34 años", "corto": "Depresión y fluoxetina", "situacion": "Hace dos meses está triste casi todo el día, dejó de disfrutar lo que antes le gustaba y duerme mal. Su médica le receta fluoxetina.", "contexto": "Hay poca señal de serotonina en las sinapsis que regulan el ánimo. La serotonina se libera desde vesículas cuando llega un potencial de acción, y su señal termina cuando sale de la hendidura. La fluoxetina bloquea el transportador de serotonina (SERT).", "foto": "img/sinapsis/casos/isrs.jpg", "foto_t": "Caja y cápsulas de fluoxetina de 20 mg.", "foto_pie": "Lanfear''s Bane · CC BY-SA 3.0 · Wikimedia Commons", "pasos": [{"tipo": "tarjeta", "nombre": "Sitio", "p": "¿Dónde está el SERT que bloquea la fluoxetina?", "ops": ["Botón presináptico", "Hendidura sináptica", "Receptor postsináptico", "Astrocito vecino"], "ok": 0, "pista": "El SERT devuelve la serotonina a la neurona que la liberó."}, {"tipo": "elegir", "nombre": "Qué cambia", "p": "¿Qué pasa con la serotonina en la hendidura?", "ops": ["Aumenta: no se recapta", "Disminuye: no se libera", "Aumenta: se libera más", "Disminuye: se degrada más"], "ok": 0, "pista": "Si su salida está bloqueada, ¿se va o se queda en la hendidura?"}, {"tipo": "elegir", "nombre": "Qué se observa", "p": "¿Cuándo mejora el ánimo de Camila?", "ops": ["En semanas: las neuronas se adaptan", "En minutos: la serotonina sube rápido", "En horas: el fármaco llega al encéfalo", "En días: se libera más serotonina"], "ok": 0, "pista": "La serotonina sube pronto, pero el ánimo no cambia al mismo ritmo. ¿Qué tienen que hacer las neuronas primero?"}], "exp": "Los ISRS, como la fluoxetina, bloquean el SERT del botón presináptico. Sin recaptación, la serotonina se queda más tiempo en la hendidura y sigue activando los receptores postsinápticos. El ánimo mejora recién en 2 a 6 semanas, porque las neuronas tienen que adaptarse, por ejemplo ajustando sus receptores. La serotonina la recaptura sobre todo la propia neurona; el glutamato, en cambio, lo recaptan principalmente los astrocitos.", "fila": ["Botón presináptico (SERT)", "Serotonina", "Más serotonina en la hendidura", "El ánimo mejora en semanas"]}, {"clave": "acv", "titulo": "Jorge, 67 años", "corto": "ACV isquémico", "situacion": "Estaba almorzando cuando de repente no pudo mover el brazo izquierdo, se le cayó el lado izquierdo de la boca y empezó a hablar arrastrando las palabras. Llega a urgencias una hora después. Un examen de imagen muestra una arteria del encéfalo tapada por un coágulo.", "contexto": "Una zona del encéfalo quedó sin oxígeno ni glucosa, y sus células casi no producen ATP. Sin ATP fallan la bomba de Na⁺/K⁺ y los transportadores que retiran el glutamato de la hendidura, que dependen del gradiente de Na⁺. En el centro de la zona las neuronas mueren en minutos; alrededor queda la penumbra, con menos flujo de sangre.", "foto": "img/sinapsis/casos/acv.jpg", "foto_t": "Tomografía del encéfalo, corte horizontal: infarto ya establecido de la arteria cerebral media derecha. La zona más oscura, a la izquierda de la imagen (se mira desde los pies del paciente), es tejido que murió.", "foto_pie": "Lucien Monfils · CC BY-SA 4.0 · Wikimedia Commons", "pasos": [{"tipo": "tarjeta", "nombre": "Sitio", "p": "¿Dónde están la mayoría de los transportadores de glutamato que fallan?", "ops": ["Botón presináptico", "Hendidura sináptica", "Receptor postsináptico", "Astrocito vecino"], "ok": 3, "pista": "Recuerda el ciclo glutamato-glutamina del práctico 2: ¿qué célula capta el glutamato y lo devuelve como glutamina?"}, {"tipo": "elegir", "nombre": "Qué cambia", "p": "¿Qué hace el exceso de glutamato en la neurona postsináptica?", "ops": ["Abre sus receptores y entra Ca²⁺", "Abre sus receptores y sale Ca²⁺", "Bloquea sus receptores y no entra Na⁺", "Cierra sus receptores y no sale K⁺"], "ok": 0, "pista": "El glutamato es excitatorio: abre canales. Del práctico 3: ¿dónde hay más Ca²⁺, dentro o fuera de la neurona?"}, {"tipo": "elegir", "nombre": "Qué se observa", "p": "A Jorge le destapan la arteria a las 2 horas. ¿Qué se espera?", "ops": ["Mejora en parte: se salva la penumbra", "Mejora del todo: revive el centro", "No mejora: ya murió toda la zona", "Mejora en parte: la glía las reemplaza"], "ok": 0, "pista": "Las neuronas del centro murieron en minutos. ¿Qué pasa con las de la penumbra si la sangre vuelve a tiempo?"}], "exp": "En el ACV isquémico falta oxígeno y glucosa. Sin ATP fallan la bomba de Na⁺/K⁺ y los transportadores de los astrocitos, que ya no retiran el glutamato de la hendidura. El glutamato acumulado activa de más sus receptores (sobre todo NMDA) y entra mucho Ca²⁺ a la neurona, lo que activa enzimas que la destruyen: es la excitotoxicidad. El centro de la zona muere en minutos, pero la penumbra se puede salvar si la arteria se destapa en las primeras horas («tiempo es cerebro»). Las neuronas muertas no se reemplazan: los astrocitos forman una cicatriz.", "fila": ["Astrocito (recaptación de glutamato)", "Glutamato", "Más glutamato: entra Ca²⁺", "Se salva la penumbra si se trata a tiempo"]}, {"clave": "parkinson", "titulo": "Luis, 68 años", "corto": "Parkinson y L-dopa", "situacion": "Hace un año le tiembla la mano derecha cuando está en reposo. Camina con pasos cortos, se mueve lento y le cuesta abrochar botones. Su neurólogo le receta L-dopa.", "contexto": "Murió gran parte de las neuronas de la sustancia negra, que envían sus axones al estriado y ahí liberan dopamina. La dopamina no sirve como fármaco para esta enfermedad: se usa L-dopa, la molécula con la que las neuronas fabrican dopamina.", "pasos": [{"tipo": "tarjeta", "nombre": "Sitio", "p": "¿Dónde falla la sinapsis del estriado en el Parkinson?", "ops": ["Botón presináptico", "Hendidura sináptica", "Receptor postsináptico", "Astrocito vecino"], "ok": 0, "pista": "Las neuronas que murieron, ¿son las que liberan la dopamina o las que la reciben?"}, {"tipo": "elegir", "nombre": "Qué cambia", "p": "¿Qué pasa con la dopamina en el estriado?", "ops": ["Disminuye: se libera menos", "Aumenta: no se recapta", "Disminuye: se degrada más", "Aumenta: se libera más"], "ok": 0, "pista": "Si faltan las neuronas que la liberan, ¿llega más o menos dopamina a la hendidura?"}, {"tipo": "elegir", "nombre": "Qué se observa", "p": "¿Por qué funciona la L-dopa y no la dopamina?", "ops": ["Cruza la barrera y se convierte en dopamina", "No cruza la barrera y actúa desde la sangre", "Cruza la barrera y bloquea la recaptación", "No cruza la barrera y activa los músculos"], "ok": 0, "pista": "Recuerda «¿Qué cruza la barrera?» del práctico 2: la L-dopa y la dopamina estaban en tarjetas distintas."}], "exp": "En el Parkinson mueren las neuronas dopaminérgicas de la sustancia negra que liberan dopamina en el estriado. Sin dopamina se altera el circuito de los ganglios basales que facilita el movimiento: aparecen temblor de reposo, lentitud y rigidez. La dopamina no cruza la barrera hematoencefálica; la L-dopa sí, con un transportador, y las neuronas que quedan la convierten en dopamina. Como las neuronas siguen muriendo, con los años el efecto de cada dosis dura menos.", "fila": ["Botón presináptico (sustancia negra → estriado)", "Dopamina", "Menos dopamina en el estriado", "Temblor y lentitud; mejora con L-dopa"]}, {"clave": "miastenia", "titulo": "Ana, 29 años", "corto": "Miastenia gravis", "situacion": "Al final del día se le caen los párpados y ve doble. Si habla mucho rato la voz se le apaga, y le cuesta masticar al terminar de comer. Todo mejora después de descansar.", "contexto": "Es una enfermedad autoinmune: anticuerpos atacan una proteína de la placa motora. Los nervios conducen bien y liberan acetilcolina en cantidad normal. Se trata con piridostigmina, que inhibe la acetilcolinesterasa.", "pasos": [{"tipo": "tarjeta", "nombre": "Sitio", "p": "Si el nervio libera acetilcolina normal, ¿dónde está la proteína que atacan los anticuerpos?", "ops": ["Botón presináptico", "Hendidura sináptica", "Receptor postsináptico", "Astrocito vecino"], "ok": 2, "pista": "El problema no está en quien envía la señal, sino en quien la recibe."}, {"tipo": "elegir", "nombre": "Qué cambia", "p": "¿Qué hace la piridostigmina con la acetilcolina en la hendidura?", "ops": ["Aumenta: no se degrada", "Disminuye: se degrada más", "Aumenta: se libera más", "Disminuye: no se libera"], "ok": 0, "pista": "La acetilcolinesterasa es la enzima que degrada la acetilcolina. Si está inhibida, ¿la acetilcolina dura más o menos?"}, {"tipo": "elegir", "nombre": "Qué se observa", "p": "¿Por qué la debilidad de Ana aumenta con el uso?", "ops": ["Cada impulso libera menos ACh y no se alcanza el umbral", "Cada impulso libera más ACh y se bloquean los receptores", "Cada impulso gasta Ca²⁺ y el nervio deja de conducir", "Cada impulso daña la mielina del nervio motor"], "ok": 0, "pista": "Con pocos receptores, el potencial de la placa queda justo. Del práctico 3: ¿qué pasa si una despolarización no llega al umbral?"}], "exp": "En la miastenia gravis, anticuerpos destruyen los receptores nicotínicos de acetilcolina de la placa motora. Con menos receptores, el potencial de placa es más pequeño: en reposo alcanza el umbral, pero con el uso repetido cada impulso libera algo menos de acetilcolina y algunas fibras musculares no llegan al umbral. Por eso la debilidad aumenta con el uso y afecta sobre todo párpados, ojos, voz y deglución. La piridostigmina inhibe la acetilcolinesterasa: la acetilcolina dura más en la hendidura y activa los receptores que quedan.", "fila": ["Receptor postsináptico (nicotínico)", "Acetilcolina", "Menos receptores; la piridostigmina deja más ACh", "Debilidad que aumenta con el uso"]}, {"clave": "botox", "titulo": "Patricia, 55 años", "corto": "Toxina botulínica en la espasticidad", "situacion": "Hace un año tuvo un ACV. Desde entonces la mano y el codo izquierdos están rígidos y flexionados, y le cuesta abrir la mano para vestirse. Antes de la terapia le inyectan toxina botulínica en los músculos flexores de los dedos.", "contexto": "La toxina botulínica corta una proteína (SNAP-25) que las vesículas necesitan para fusionarse con la membrana. Se inyecta en el músculo y actúa solo cerca del lugar de la inyección. Su efecto dura unos tres meses.", "pasos": [{"tipo": "tarjeta", "nombre": "Sitio", "p": "¿Dónde actúa la toxina botulínica?", "ops": ["Botón presináptico", "Hendidura sináptica", "Receptor postsináptico", "Astrocito vecino"], "ok": 0, "pista": "¿Dónde están las vesículas que necesitan fusionarse para liberar el neurotransmisor?"}, {"tipo": "elegir", "nombre": "Qué cambia", "p": "¿Qué pasa con la acetilcolina en la placa motora?", "ops": ["Disminuye: no se libera", "Aumenta: no se degrada", "Disminuye: se degrada más", "Aumenta: no se recapta"], "ok": 0, "pista": "Si las vesículas no se fusionan, ¿sale su contenido a la hendidura?"}, {"tipo": "elegir", "nombre": "Qué se observa", "p": "¿Por qué el efecto dura solo unos tres meses?", "ops": ["Brotan terminales nuevas que liberan ACh", "Se forman receptores nuevos en el músculo", "Se regenera la mielina del nervio motor", "Nacen motoneuronas nuevas en la médula"], "ok": 0, "pista": "La toxina no mata a la neurona: ¿qué puede hacer su terminal para recuperar la sinapsis?"}], "exp": "La toxina botulínica corta SNAP-25, una proteína del complejo que fusiona la vesícula con la membrana. Sin fusión no se libera acetilcolina y el músculo inyectado se relaja: es una parálisis local y reversible. En la espasticidad abre una ventana para estirar y entrenar en terapia; en Fono se usa, por ejemplo, en la disfonía espasmódica. El efecto dura unos tres meses porque brotan terminales nuevas y después se recupera la original. En el botulismo, la misma toxina llega a todo el cuerpo y causa una parálisis generalizada.", "fila": ["Botón presináptico (fusión de vesículas)", "Acetilcolina", "No se libera ACh", "El músculo se relaja por unos tres meses"]}]}]}', NULL, 1);
INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (17, 1, 'En Fonoaudiología: muchos de tus pacientes reciben fármacos que actúan en la sinapsis; por ejemplo, la toxina botulínica se usa en la disfonía espasmódica y en la sialorrea. Saber dónde actúa cada uno te ayuda a anticipar sus efectos en la voz, el habla y la deglución.', 1),
  (17, 2, 'En Terapia Ocupacional: la toxina botulínica se usa para reducir la espasticidad antes de la terapia, y enfermedades como la miastenia gravis o el Parkinson cambian la fuerza y el movimiento en las actividades diarias. Saber dónde actúa cada fármaco te ayuda a planificar la intervención.', 2);
